-- ==== db/migrations/0054_20260812_challenge_window_release_seam.sql ===============================
-- ════════════════════════════════════════════════════════════════════════════════════════════════
-- 0054 · PHASE 11-E — the challenge window: the safety seam between death_verified and released
-- ════════════════════════════════════════════════════════════════════════════════════════════════
--
-- ★ WHAT THIS PHASE INSERTS, AND WHY IT EXISTS. 11-D let `after_verified_death` satisfy at
-- `death_verified`. That connected verification directly to irreversible disclosure — and disclosure
-- cannot be undone (R15: revoking future access is possible; undoing disclosure is not). 11-E
-- inserts the missing safety states between them:
--
--     active → death_verification_pending → death_verified
--            → challenge_window            (verification accepted; release deliberately waiting;
--                                           the owner has been notified and can object)
--            → released                    (the ONLY lifecycle at which owner-authored
--                                           death-conditioned grants may evaluate as satisfied)
--     any pre-released death-process state
--            → challenge_halted            (the authenticated owner objected; terminal in 11-E)
--
-- The predicate change rides in `release_conditions.sql`: `after_verified_death` is FALSE at
-- death_verified, FALSE throughout challenge_window, FALSE at challenge_halted, TRUE only at
-- released. So this migration making `released` STORABLE widens no disclosure: the only writer is
-- `release_estate` (client-revoked, no reachable door in 11-E), behind an elapsed, configured,
-- owner-notified, unchallenged window.
--
-- ★ THE WINDOW DURATION IS CONFIGURATION, NOT A GUESS. `release_safety_policy` ships EMPTY: no
-- default duration is seeded, because the duration is a product decision this phase does not own.
-- Fail-closed direction: an estate can always ENTER the challenge window (the owner-safety clock
-- and notice), but with no configured duration the window NEVER ELAPSES and release refuses with
-- `release_window_not_configured`. The duration is re-read LIVE at release time (the H2 precedent:
-- a policy tightened mid-window tightens the window) — never stamped at entry.
--
-- ★ THE OWNER CHALLENGE IS CHEAPER THAN THE CLAIM (R13) AND WINS TIES (R14). No evidence, no
-- review, no waiting period, no designation — one authenticated owner action. The tiebreak is
-- structural: release requires the window STRICTLY elapsed (`now() > notified_at + duration`), so
-- at the exact boundary instant release refuses while challenge still succeeds; both transitions
-- serialize on the lifecycle row lock, and nothing transitions out of challenge_halted.
--
-- IDEMPOTENT. Safe to re-apply. APPLY ORDER: after 0052/0053, inside the bundles that carry it.

-- [psql meta-command removed for the SQL editor] \set ON_ERROR_STOP on

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- 1 · WIDEN the lifecycle vocabulary to the six-state safety machine. Additive only.
-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- The constraint name is resolved from the catalog, not guessed (the 0051 lesson).
do $$
declare
  v_name text;
begin
  for v_name in
    select con.conname
      from pg_constraint con
      join pg_class rel on rel.oid = con.conrelid
      join pg_namespace nsp on nsp.oid = rel.relnamespace
     where nsp.nspname = 'public'
       and rel.relname = 'estate_lifecycle'
       and con.contype = 'c'
       and pg_get_constraintdef(con.oid) ilike '%state%'
  loop
    execute format('alter table public.estate_lifecycle drop constraint %I', v_name);
  end loop;

  alter table public.estate_lifecycle
    add constraint estate_lifecycle_state_check
    check (state in (
      'active',
      'death_verification_pending',
      'death_verified',
      -- Phase 11-E: the safety seam. Storable here; REACHABLE only through the closed transition
      -- map in apply_estate_lifecycle_transition, and 'released' only through release_estate.
      'challenge_window',
      'challenge_halted',
      'released'
    ));
end $$;

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- 2 · THE SAFETY FACTS live on the lifecycle row: when the owner was notified, when the window
--     opened, when it was halted or released, and WHICH notification row is the safety notice.
--     Facts, never authority — release re-derives everything live.
-- ────────────────────────────────────────────────────────────────────────────────────────────────
alter table public.estate_lifecycle add column if not exists owner_notified_at            timestamptz;
alter table public.estate_lifecycle add column if not exists challenge_window_started_at  timestamptz;
alter table public.estate_lifecycle add column if not exists halted_at                    timestamptz;
alter table public.estate_lifecycle add column if not exists released_at                  timestamptz;
alter table public.estate_lifecycle add column if not exists safety_notification_id       uuid;

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- 3 · A HALTED CASE IS ITS OWN STATUS. The owner challenge halts any open case; 'cancelled' means
--     the initiator withdrew and reusing it would erase the difference between "the claimant
--     changed their mind" and "the owner said they are alive" — facts with different forensics.
-- ────────────────────────────────────────────────────────────────────────────────────────────────
do $$
declare
  v_name text;
begin
  for v_name in
    select con.conname
      from pg_constraint con
      join pg_class rel on rel.oid = con.conrelid
      join pg_namespace nsp on nsp.oid = rel.relnamespace
     where nsp.nspname = 'public'
       and rel.relname = 'death_verification_cases'
       and con.contype = 'c'
       and pg_get_constraintdef(con.oid) ilike '%status%'
       and pg_get_constraintdef(con.oid) not ilike '%event_type%'
       and pg_get_constraintdef(con.oid) not ilike '%review_status%'
       and pg_get_constraintdef(con.oid) not ilike '%initiator_capacity%'
  loop
    execute format('alter table public.death_verification_cases drop constraint %I', v_name);
  end loop;

  alter table public.death_verification_cases
    add constraint death_verification_cases_status_check
    check (status in ('open', 'verified', 'rejected', 'cancelled',
                      -- Phase 11-E: set only by the owner-challenge routine.
                      'halted'));
end $$;

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- 4 · THE WINDOW-DURATION CONFIGURATION — one row, definer-only, DELIBERATELY UNSEEDED.
-- ────────────────────────────────────────────────────────────────────────────────────────────────
create table if not exists public.release_safety_policy (
  -- Single-row table: the PK admits exactly `true`.
  id               boolean     primary key default true check (id),
  challenge_window interval    not null,
  updated_at       timestamptz not null default now()
);

alter table public.release_safety_policy enable row level security;
-- ZERO grants, ZERO policies — reachable only through the DEFINER reader. No seed row: the
-- duration is a product/operator decision recorded by an explicit, reviewed INSERT, and until it
-- exists the release window cannot elapse anywhere.

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- 5 · PROVE THE SEAM TOOK, IN THE MIGRATION ITSELF (both directions, the 0051/0052 discipline).
-- ────────────────────────────────────────────────────────────────────────────────────────────────
do $$
declare
  v_def text;
begin
  select pg_get_constraintdef(con.oid) into v_def
    from pg_constraint con
    join pg_class rel on rel.oid = con.conrelid
    join pg_namespace nsp on nsp.oid = rel.relnamespace
   where nsp.nspname = 'public' and rel.relname = 'estate_lifecycle'
     and con.contype = 'c' and pg_get_constraintdef(con.oid) ilike '%state%';
  if v_def is null then
    raise exception '0054 FAILED: estate_lifecycle has no state CHECK after the widening';
  end if;
  if position('challenge_window' in v_def) = 0
     or position('challenge_halted' in v_def) = 0
     or position('released' in v_def) = 0 then
    raise exception '0054 FAILED: the safety vocabulary is incomplete: %', v_def;
  end if;
  if (select count(*) from regexp_matches(v_def, '''[a-z_]+''', 'g')) <> 6 then
    raise exception '0054 FAILED: the lifecycle vocabulary is not exactly six states: %', v_def;
  end if;
  -- 'frozen' and other invented states must still be unrepresentable.
  if position('frozen' in v_def) > 0 then
    raise exception '0054 FAILED: an unapproved lifecycle state is storable: %', v_def;
  end if;

  select pg_get_constraintdef(con.oid) into v_def
    from pg_constraint con
    join pg_class rel on rel.oid = con.conrelid
    join pg_namespace nsp on nsp.oid = rel.relnamespace
   where nsp.nspname = 'public' and rel.relname = 'death_verification_cases'
     and con.conname = 'death_verification_cases_status_check';
  if v_def is null or position('halted' in v_def) = 0 then
    raise exception '0054 FAILED: the case status vocabulary did not gain ''halted'': %',
      coalesce(v_def, '<absent>');
  end if;

  -- The policy table is definer-only and EMPTY: a seeded duration would be a product decision
  -- taken by a migration.
  if exists (
    select 1 from information_schema.role_table_grants
     where table_schema = 'public' and table_name = 'release_safety_policy'
       and grantee in ('anon', 'authenticated')
  ) then
    raise exception '0054 FAILED: a client role holds a grant on release_safety_policy';
  end if;
  if (select count(*) from public.release_safety_policy) <> 0 then
    -- On RE-application to a database whose operator later configured the window, a row is
    -- legitimate — the check refuses only a duration arriving in the SAME transaction that
    -- created the table (i.e. seeded by migration).
    if (select min(updated_at) from public.release_safety_policy) >= transaction_timestamp() then
      raise exception '0054 FAILED: release_safety_policy was seeded by this migration — the '
        'window duration is a product decision, not a default';
    end if;
  end if;

  raise notice '0054 · challenge-window seam in place (6 lifecycle states; halted case status; '
    'safety facts columns; duration configuration table EMPTY and definer-only)';
end $$;


-- ==== db/migrations/0055_20260812_release_authorization.sql =======================================
-- ════════════════════════════════════════════════════════════════════════════════════════════════
-- 0055 · PHASE 11-F — owner-liveness delivery, the two-person release rule, and the release record
-- ════════════════════════════════════════════════════════════════════════════════════════════════
--
-- ★ WHAT THE FIVE APPROVED DECISIONS CHANGE, AND WHY EACH NEEDS SCHEMA.
--
-- D1 · TWO-PERSON RULE. The operator who verifies a death may not be the operator who authorizes
--      release, and that is enforced in the DATABASE, not in a console. `release_authorizations`
--      records both reviewers as first-class columns with a CHECK that they differ — so the rule
--      survives a UI rewrite, a direct RPC call, and a future admin tool nobody has written yet.
--
-- D2 · THE CLOCK STARTS AT DISPATCH, NOT AT VERIFICATION. A seventh lifecycle state
--      (`owner_notification_dispatched`) sits between `death_verified` and `challenge_window`
--      precisely so "we accepted the death" and "we told the owner" cannot be the same fact. The
--      duration is 7 x 24h — now an approved decision, so 0055 SEEDS it (0054 deliberately did not,
--      because in 11-E it was not yet decided).
--
-- D4 · IN-APP ALONE IS INSUFFICIENT. `owner_notice_outbox` is the independently-reachable channel:
--      an email row committed in the same transaction as the dispatch transition. The requirement is
--      DISPATCH INITIATION — the row exists and is addressed — never a read receipt, an open, or an
--      acknowledgement, none of which the product can honestly observe.
--
-- ★ WHAT THIS MIGRATION STILL CANNOT DO. It creates no grant, tier, membership or designation, and
-- it makes `released` no easier to reach: the route is still `challenge_window -> released` alone,
-- now additionally gated on two distinct reviewers and a dispatched notice (D5).
--
-- IDEMPOTENT. Safe to re-apply. APPLY ORDER: after 0054, inside the bundles that carry it.

-- [psql meta-command removed for the SQL editor] \set ON_ERROR_STOP on

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- 1 · THE SEVENTH LIFECYCLE STATE — "we told the owner" is its own fact
-- ────────────────────────────────────────────────────────────────────────────────────────────────
do $$
declare v_name text;
begin
  for v_name in
    select con.conname
      from pg_constraint con
      join pg_class rel on rel.oid = con.conrelid
      join pg_namespace nsp on nsp.oid = rel.relnamespace
     where nsp.nspname = 'public' and rel.relname = 'estate_lifecycle'
       and con.contype = 'c' and pg_get_constraintdef(con.oid) ilike '%state%'
  loop
    execute format('alter table public.estate_lifecycle drop constraint %I', v_name);
  end loop;

  alter table public.estate_lifecycle
    add constraint estate_lifecycle_state_check
    check (state in (
      'active',
      'death_verification_pending',
      'death_verified',
      -- Phase 11-F (D2): the owner has been told, and the challenge clock has started.
      'owner_notification_dispatched',
      'challenge_window',
      'challenge_halted',
      'released'
    ));
end $$;

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- 2 · THE OWNER NOTICE OUTBOX — the independently reachable channel (D4)
-- ────────────────────────────────────────────────────────────────────────────────────────────────
--
-- ★ A SEPARATE TABLE FROM `invitation_delivery_outbox`, DELIBERATELY. That outbox is FK-bound to an
-- invitation and drained by a daily cron whose claim predicate has no age bound — the right class
-- for an invitation email and the wrong one for the notice that starts a release clock. Sharing it
-- would silently inherit both properties.
--
-- ★ THE RECIPIENT IS RESOLVED AND STORED AT DISPATCH. Storing the address is what makes
-- "independently reachable" a checkable fact rather than an assumption: a dispatch with no
-- resolvable address must FAIL, not queue a row nobody can deliver.
create table if not exists public.owner_notice_outbox (
  id            uuid        primary key default gen_random_uuid(),
  estate_id     uuid        not null references public.estates(id) on delete cascade,
  user_id       uuid        not null references auth.users(id),
  -- Email is the minimum bar (D4). Push, when it exists, is SUPPLEMENTAL and joins this CHECK by a
  -- reviewed migration — it never replaces the email row.
  channel       text        not null default 'email' check (channel in ('email')),
  recipient     text        not null,
  notice_kind   text        not null check (notice_kind in ('death_process.window_opened')),
  status        text        not null default 'queued'
    check (status in ('queued', 'processing', 'dispatched', 'failedPermanent', 'cancelled')),
  requested_at  timestamptz not null default now(),
  dispatched_at timestamptz,
  attempts      int         not null default 0,
  next_attempt_at timestamptz,
  failure_class text,
  purge_audit_id uuid
);

create index if not exists owner_notice_outbox_estate_idx on public.owner_notice_outbox (estate_id);
create index if not exists owner_notice_outbox_claimable_idx
  on public.owner_notice_outbox (requested_at) where status in ('queued', 'processing');

alter table public.owner_notice_outbox enable row level security;
-- ZERO grants, ZERO policies: a row here names a living owner's email address and the fact that a
-- death process is running against their estate. Only DEFINER routines may touch it.

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- 3 · THE RELEASE AUTHORIZATION RECORD — its own model, never overloaded (Stage 5)
-- ────────────────────────────────────────────────────────────────────────────────────────────────
--
-- ★ NOT A CLAIM PACKET, NOT A MEMBERSHIP, NOT A DESIGNATION. Each of those answers a different
-- question with a different actor, evidence and reversibility; overloading one of them to carry
-- "two operators authorized this release" is how a fact acquires the wrong lifecycle. This table
-- exists so the release event has a home with exactly the fields the audit needs.
--
-- ★ THE TWO-PERSON RULE IS A TABLE CONSTRAINT (D1). Not a trigger, not a routine-only check: a CHECK
-- means no INSERT anywhere — routine, migration, console, future admin tool — can record a release
-- authorized by one person. The routine enforces it too; this is the layer that cannot be bypassed.
create table if not exists public.release_authorizations (
  id            uuid        primary key default gen_random_uuid(),
  estate_id     uuid        not null references public.estates(id) on delete cascade,
  case_id       uuid        not null references public.death_verification_cases(id),
  -- reviewer_a VERIFIED THE DEATH. reviewer_b AUTHORIZED THE RELEASE. They must differ.
  reviewer_a    uuid        not null references auth.users(id),
  reviewer_b    uuid        not null references auth.users(id),
  verified_at   timestamptz not null,
  authorized_at timestamptz not null default now(),
  released_at   timestamptz,
  audit_reason  text        not null,
  constraint release_authorizations_two_person check (reviewer_a <> reviewer_b)
);

-- One authorization per estate: release is not a thing that happens twice.
create unique index if not exists release_authorizations_one_per_estate
  on public.release_authorizations (estate_id);

alter table public.release_authorizations enable row level security;
-- ZERO grants, ZERO policies — DEFINER-routine-only, like every other record on this path.

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- 4 · THE PURGE AUDIT — nothing is ever silently deleted (Stage 3)
-- ────────────────────────────────────────────────────────────────────────────────────────────────
create table if not exists public.outbox_purge_audit (
  id            uuid        primary key default gen_random_uuid(),
  outbox_name   text        not null,
  purged_at     timestamptz not null default now(),
  actor_id      uuid,
  row_count     int         not null,
  oldest_row_at timestamptz,
  newest_row_at timestamptz,
  reason        text        not null
);
alter table public.outbox_purge_audit enable row level security;

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- 5 · THE CHALLENGE WINDOW DURATION — 7 x 24h, now an APPROVED decision (D2)
-- ────────────────────────────────────────────────────────────────────────────────────────────────
--
-- ★ 0054 DELIBERATELY SEEDED NOTHING, AND THAT WAS RIGHT THEN. In 11-E the duration was undecided,
-- so the fail-closed posture was "no window can ever elapse". D2 decides it, so it is recorded here
-- — in a migration, reviewably, once — rather than left to an operator's console session where
-- nobody could later say what value production carries or when it changed.
--
-- `on conflict do update` is deliberate: re-applying this migration re-asserts the approved value,
-- so a hand-edited production row is corrected by the next paste rather than silently kept.
insert into public.release_safety_policy (id, challenge_window)
values (true, interval '7 days')
on conflict (id) do update set challenge_window = excluded.challenge_window, updated_at = now();

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- 6 · REMOVE the one-person release lever
-- ────────────────────────────────────────────────────────────────────────────────────────────────
--
-- ★ THE 0053 PRECEDENT, APPLIED TO AN ACTOR RATHER THAN AN ARGUMENT. 11-E's `release_estate(uuid)`
-- had no concept of a second reviewer. Leaving it in place beside the two-person door would be a
-- second release path that bypasses D1 entirely — and `create or replace` cannot remove it, because
-- the replacement has a different name and signature. It is DROPPED, so a caller that was never
-- rewired fails loudly instead of releasing on one person's say-so.
drop function if exists public.release_estate(uuid);

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- 7 · PROVE IT TOOK, IN THE MIGRATION ITSELF (both directions)
-- ────────────────────────────────────────────────────────────────────────────────────────────────
do $$
declare v_def text; v_n int;
begin
  select pg_get_constraintdef(con.oid) into v_def
    from pg_constraint con
    join pg_class rel on rel.oid = con.conrelid
    join pg_namespace nsp on nsp.oid = rel.relnamespace
   where nsp.nspname = 'public' and rel.relname = 'estate_lifecycle'
     and con.contype = 'c' and pg_get_constraintdef(con.oid) ilike '%state%';
  if v_def is null or position('owner_notification_dispatched' in v_def) = 0 then
    raise exception '0055 FAILED: the dispatch state is not storable: %', coalesce(v_def, '<absent>');
  end if;
  if (select count(*) from regexp_matches(v_def, '''[a-z_]+''', 'g')) <> 7 then
    raise exception '0055 FAILED: the lifecycle vocabulary is not exactly seven states: %', v_def;
  end if;

  -- The two-person CHECK must exist as a CONSTRAINT, not merely as routine logic.
  if not exists (
    select 1 from pg_constraint where conname = 'release_authorizations_two_person'
  ) then
    raise exception '0055 FAILED: the two-person rule is not a table constraint — routine-only '
      'enforcement can be bypassed by any other writer';
  end if;
  -- …and it must actually refuse. Proven, not assumed.
  begin
    insert into public.release_authorizations
      (estate_id, case_id, reviewer_a, reviewer_b, verified_at, audit_reason)
    select e.id, c.id, c.initiated_by, c.initiated_by, now(), '0055 self-check'
      from public.estates e join public.death_verification_cases c on c.estate_id = e.id limit 1;
    -- If a row existed to try with AND the insert succeeded, the constraint is not working.
    get diagnostics v_n = row_count;
    if v_n > 0 then
      raise exception '0055 FAILED: a single-reviewer release authorization was insertable';
    end if;
  exception when check_violation then
    null; -- the constraint refused, which is the point
  end;

  -- ★ THE TABLE, NOT THE READER. `challenge_window_duration()` lives in `release_safety.sql`, which
  -- ships in a LATER bundle — so a migration that asked the function would raise on the first paste
  -- of the release-conditions bundle, where 0055 legitimately runs before that function exists. A
  -- migration must be checkable against the schema it changed, not against a function some other
  -- artifact happens to carry.
  if (select p.challenge_window from public.release_safety_policy p where p.id)
     is distinct from interval '7 days' then
    raise exception '0055 FAILED: the challenge window is % (expected 7 days per D2)',
      (select p.challenge_window from public.release_safety_policy p where p.id);
  end if;

  if to_regprocedure('public.release_estate(uuid)') is not null then
    raise exception '0055 FAILED: the one-person release lever still exists — D1 would be bypassable';
  end if;

  if exists (
    select 1 from information_schema.role_table_grants
     where table_schema = 'public'
       and table_name in ('owner_notice_outbox', 'release_authorizations', 'outbox_purge_audit')
       and grantee in ('anon', 'authenticated')
  ) then
    raise exception '0055 FAILED: a client role holds a grant on a release-path table';
  end if;

  raise notice '0055 · release authorization in place (7 lifecycle states; owner notice outbox; '
    'two-person CHECK enforced; window = 7 days; one-person lever dropped)';
end $$;


-- ==== db/functions/estate_lifecycle_state.sql =====================================================
-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- estate_lifecycle_state(p_estate) → text            [INTERNAL — the authoritative lifecycle read]
-- ────────────────────────────────────────────────────────────────────────────────────────────────
--
-- ★ EXTRACTED FROM `death_verification.sql` IN PHASE 11-D, because the seam changed sides. In 11-C
-- this reader existed for the death-verification routines and was consulted by nobody else — that
-- absence was the firewall. In 11-D the canonical release predicate consumes lifecycle state as an
-- argument, so every disclosure evaluator resolves it at read time. The reader therefore ships in
-- `release_conditions_bundle.sql` (the FIRST artifact an operator pastes), so that no paste order
-- ever leaves a consumer referencing a reader that does not exist yet. The death-verification
-- bundle also carries it (idempotent re-create), keeping that artifact single-paste runnable.
--
-- ★ ABSENT ROW = 'active'. An estate that has never seen a death-verification case has no row in
-- `estate_lifecycle`, and this reader answers the base state. The empty table is a correct table.
--
-- ★ THE CLOSED SET IS THE TABLE'S, NOT THIS FUNCTION'S. The CHECK on `estate_lifecycle.state`
-- (migration 0052) admits exactly 'active' / 'death_verification_pending' / 'death_verified', and
-- the canonical predicate REFUSES any lifecycle value outside that set — so a state this reader
-- could never produce fails closed at the predicate rather than being interpreted.
--
-- ★ NO CLIENT MAY EXECUTE THIS. A client that can map estate → lifecycle state has been handed a
-- death-status oracle for arbitrary estates. Its callers are SECURITY DEFINER routines (the
-- death-verification module and the disclosure evaluators) and the SQL suite. The disclosure rule
-- for consumers is pinned by `test/deathVerificationFoundation.test.ts`: outside the death module,
-- this function may appear ONLY as the lifecycle argument of `public.release_condition_satisfied` —
-- never as the subject of a local comparison, which would be release policy leaking out of the
-- canonical predicate one `if` at a time.
create or replace function public.estate_lifecycle_state(p_estate uuid)
 returns text
 language sql
 security definer
 stable
 set search_path to 'public'
as $function$
  select coalesce(
    (select l.state from public.estate_lifecycle l where l.estate_id = p_estate),
    'active');
$function$;
revoke execute on function public.estate_lifecycle_state(uuid) from public, anon, authenticated;

comment on function public.estate_lifecycle_state(uuid) is
  'THE authoritative estate lifecycle read (Phase 11-C, extracted 11-D). Absent row = active. '
  'INTERNAL: execute revoked from every client role — a client that can map estate to lifecycle '
  'state holds a death-status oracle. Consumed by the death-verification routines and, since 11-D, '
  'as the lifecycle argument to public.release_condition_satisfied inside disclosure evaluators. '
  'Never derived from claim_packets.status, evidence, or attained verification levels.';


-- ==== db/functions/death_verification.sql =========================================================
-- ════════════════════════════════════════════════════════════════════════════════════════════════
-- PHASE 11-C · DEATH-VERIFICATION ROUTINES — initiation, evidence, review, decision, lifecycle
-- ════════════════════════════════════════════════════════════════════════════════════════════════
--
-- ★ NOTHING IN THIS FILE RELEASES ANYTHING. No routine here writes `access_grants`, `documents`,
-- `encrypted_instructions`, `claim_packets`, `notifications`, or any visibility tier. No routine
-- calls `release_condition_satisfied`, `estate_release_state`, or any disclosure projection. The
-- case is a record of facts about verification — it is never an access instrument, and the Phase
-- 11-C suite proves every state it can reach leaves every viewer's composed payload byte-identical.
--
-- ★ THE GATES LIVE INSIDE THE DEFINERS (the DEFINER-door discipline). Every client-reachable
-- routine re-derives its own authority; nothing trusts a wrapper.
--
-- ★ REFUSAL SHAPE. For the client-reachable routines the unauthorized answer is ONE sentinel —
-- `not_authorized` (42501) — for every cause an unauthenticated identity check does not cover:
-- nonexistent estate, real-but-foreign estate, nonexistent case, foreign case, wrong role, revoked
-- designation. The gate runs BEFORE any existence lookup can differentiate, so a probe cannot use
-- refusal bytes to learn whether an estate or case exists (T9: case existence is itself protected).
-- `auth_required` for a missing session is the one distinguishable cause, matching every existing
-- gate in the repo. Admin routines may name their causes — an authenticated platform admin behind
-- AAL2 + freshness is authorized to know a case exists.
--
-- ★ REQUIRED ≥ ATTAINED IS ENFORCED HERE (H2 closed). `admin_decide_death_verification_case`
-- re-derives the required level LIVE at decision time and refuses `verify` unless the attained
-- level meets it. The initiation-time snapshot on the case row is a record for the case file,
-- never the enforcement input — a policy tightened mid-case tightens the case.
--
-- Deploys via `db/bundles/death_verification_bundle.sql` (migration 0052 + the lifecycle reader +
-- this file). Source of truth — re-apply on DB reset.
--
-- ★ `estate_lifecycle_state` MOVED OUT IN PHASE 11-D — see `db/functions/estate_lifecycle_state.sql`.
-- The reader now ships with the release-conditions bundle (the disclosure evaluators consume it as
-- the predicate's lifecycle argument, and the FIRST pasted artifact must carry the seam so no paste
-- order leaves a consumer referencing a reader that does not exist). The routines below still call
-- it at execution time; the death bundle carries the same source file so it stays single-paste
-- runnable.

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- apply_estate_lifecycle_transition(p_estate, p_to, p_case, p_reason) → void          [INTERNAL]
-- ────────────────────────────────────────────────────────────────────────────────────────────────
--
-- ★ THE ONLY WRITER of `estate_lifecycle`, and the transition map is written out as the closed set
-- it is. Ten legal moves since 11-F:
--
--     active                        → death_verification_pending   (case initiated)
--     death_verification_pending    → active                       (case rejected / cancelled)
--     death_verification_pending    → death_verified               (admin decision, attained ≥ required)
--     death_verified                → owner_notification_dispatched (11-F: the owner was TOLD — D2/D4)
--     owner_notification_dispatched → challenge_window             (the clock is running)
--     death_verification_pending    → challenge_halted             (owner challenge)
--     death_verified                → challenge_halted             (owner challenge)
--     owner_notification_dispatched → challenge_halted             (owner challenge — 11-F)
--     challenge_window              → challenge_halted             (owner challenge)
--     challenge_window              → released                     (two-person authorization — 11-F)
--
-- ★ THE 11-F INSERTION IS THE POINT: `death_verified → challenge_window` IS GONE. A window may only
-- open on an estate whose owner has actually been sent an independently-reachable notice, so the
-- edge that skipped the notice no longer exists — a routine that forgets to dispatch cannot open a
-- window by accident, it raises.
--
-- Everything else raises. Two absences remain the load-bearing half of the map:
--
--   · NOTHING LEAVES challenge_halted. The owner said no; there is no resume, no admin override,
--     no reopen — restoring one is a future product decision, not a bigger map (R: 11-E brief §7).
--   · NOTHING LEAVES released. Disclosure cannot be undone (R15); a post-release freeze would be a
--     new product surface, not an edge here.
--
-- And `released` is REACHABLE only through `authorize_release` (11-F), which alone checks the window
-- guards, the dispatch facts, and the TWO-PERSON rule before asking for this edge.
--
-- ★ TRANSACTIONAL + AUDITED (the 11-A §7 requirement): the current row is locked, the move is
-- validated against it, and one audit row records from/to/case/reason with the acting user.
create or replace function public.apply_estate_lifecycle_transition(
  p_estate uuid,
  p_to     text,
  p_case   uuid,
  p_reason text
)
 returns void
 language plpgsql
 security definer
 set search_path to 'public'
as $function$
declare
  v_from text;
begin
  select l.state into v_from
    from public.estate_lifecycle l
   where l.estate_id = p_estate
   for update;
  if v_from is null then
    v_from := 'active';
  end if;

  -- The closed map. An unknown current state is unreachable (table CHECK) but still refused here:
  -- unknown state fails closed, it is never a wildcard. challenge_halted and released have NO
  -- outbound edges, deliberately (see the header).
  if not (
       (v_from = 'active'                     and p_to = 'death_verification_pending')
    or (v_from = 'death_verification_pending' and p_to = 'active')
    or (v_from = 'death_verification_pending' and p_to = 'death_verified')
    or (v_from = 'death_verified'             and p_to = 'owner_notification_dispatched')
    or (v_from = 'owner_notification_dispatched' and p_to = 'challenge_window')
    or (v_from = 'death_verification_pending' and p_to = 'challenge_halted')
    or (v_from = 'death_verified'             and p_to = 'challenge_halted')
    or (v_from = 'owner_notification_dispatched' and p_to = 'challenge_halted')
    or (v_from = 'challenge_window'           and p_to = 'challenge_halted')
    or (v_from = 'challenge_window'           and p_to = 'released')
  ) then
    raise exception 'invalid_lifecycle_transition' using errcode = 'P0001';
  end if;

  insert into public.estate_lifecycle (estate_id, state, updated_at, updated_case_id)
  values (p_estate, p_to, now(), p_case)
  on conflict (estate_id) do update
    set state = excluded.state,
        updated_at = excluded.updated_at,
        updated_case_id = excluded.updated_case_id;

  perform public.write_audit(
    'estate_lifecycle.transition', 'estate_lifecycle', p_case, p_estate,
    jsonb_build_object('from_state', v_from, 'to_state', p_to,
                       'case_id', p_case, 'reason', p_reason));
end $function$;
revoke execute on function public.apply_estate_lifecycle_transition(uuid, text, uuid, text)
  from public, anon, authenticated;

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- initiate_death_verification_case(p_estate) → uuid                        [authenticated, gated]
-- ────────────────────────────────────────────────────────────────────────────────────────────────
--
-- ★ D2: initiation is DESIGNEE-ONLY — the same canonical fiduciary predicate that gates claim
-- submission (`is_estate_executor`: an ACTIVE executor or trustee designation). Membership roles,
-- disclosure tiers, professional_delegate status, and estate ownership neither qualify nor
-- disqualify: an owner without a designation is refused like any non-designee, and an owner who
-- holds one passes by the designation, exactly as `submit_claim_packet` has always answered.
--
-- ★ THE GATE RUNS BEFORE ANY EXISTENCE LOOKUP. `is_estate_executor` returns false for a
-- nonexistent estate and for a foreign one alike, so both refuse with the same bytes.
create or replace function public.initiate_death_verification_case(p_estate uuid)
 returns uuid
 language plpgsql
 security definer
 set search_path to 'public'
as $function$
declare
  v_uid          uuid := auth.uid();
  v_designation  uuid;
  v_capacity     text;
  v_state        text;
  v_juris        text;
  v_required     public.verification_level;
  v_case         uuid;
begin
  if v_uid is null then
    raise exception 'auth_required' using errcode = '42501';
  end if;
  if not public.is_estate_executor(p_estate, v_uid) then
    raise exception 'not_authorized' using errcode = '42501';
  end if;

  -- The designation that authorizes this initiation, captured as fact on the case. Deterministic
  -- when the caller holds both capacities: 'executor' precedes 'trustee' (current product
  -- semantics rank them identically for initiation; the recorded capacity is a fact, not a power).
  select d.id, d.designation_type
    into v_designation, v_capacity
    from public.estate_designations d
   where d.estate_id = p_estate
     and d.user_id = v_uid
     and d.designation_type in ('executor', 'trustee')
     and d.status = 'active'
   order by d.designation_type
   limit 1;

  -- One live death-verification process per estate. An open case holds the lifecycle at
  -- death_verification_pending; a verified case holds it at death_verified. Both refuse a new
  -- initiation. Only an authorized designee can reach this sentinel, so it is not an oracle.
  v_state := public.estate_lifecycle_state(p_estate);
  if v_state <> 'active' then
    raise exception 'lifecycle_conflict' using errcode = 'P0001';
  end if;

  select e.jurisdiction into v_juris from public.estates e where e.id = p_estate;

  -- The policy engine's answer AT INITIATION, recorded on the case. Fail-closed inside the engine:
  -- unknown / unapproved / NULL jurisdiction answers 'enhanced_kyc'. NEVER copied into attained.
  v_required := public.required_verification_level(p_estate);

  insert into public.death_verification_cases
    (estate_id, event_type, status, initiated_by, initiator_designation_id, initiator_capacity,
     jurisdiction_context, required_level_at_initiation)
  values
    (p_estate, 'death', 'open', v_uid, v_designation, v_capacity, v_juris, v_required)
  returning id into v_case;

  perform public.apply_estate_lifecycle_transition(
    p_estate, 'death_verification_pending', v_case, 'case_initiated');

  perform public.write_audit(
    'death_case.initiated', 'death_verification_cases', v_case, p_estate,
    jsonb_build_object('case_id', v_case, 'event_type', 'death',
                       'initiator_capacity', v_capacity,
                       'required_level_at_initiation', v_required::text,
                       'jurisdiction_known', v_juris is not null));
  return v_case;
end $function$;
revoke execute on function public.initiate_death_verification_case(uuid) from public, anon;
grant  execute on function public.initiate_death_verification_case(uuid) to authenticated;

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- attach_death_verification_evidence(p_case, p_document) → uuid            [authenticated, gated]
-- ────────────────────────────────────────────────────────────────────────────────────────────────
--
-- Records that a document was RECEIVED as evidence for a case. It does not review, grade, or
-- verify anything, and it touches no verification level — a thousand attachments leave the
-- attained level exactly where it was (brief §13: file upload ≠ document verification).
--
-- The document must belong to the case's estate — the multi-source-agreement rule from
-- `submit_claim_with_evidence`, one join shorter. A document in another estate and a document that
-- does not exist refuse identically.
create or replace function public.attach_death_verification_evidence(p_case uuid, p_document uuid)
 returns uuid
 language plpgsql
 security definer
 set search_path to 'public'
as $function$
declare
  v_uid        uuid := auth.uid();
  v_estate     uuid;
  v_status     text;
  v_doc_estate uuid;
  v_evidence   uuid;
begin
  if v_uid is null then
    raise exception 'auth_required' using errcode = '42501';
  end if;

  select c.estate_id, c.status into v_estate, v_status
    from public.death_verification_cases c
   where c.id = p_case;
  -- Nonexistent case and foreign case answer with the same bytes: the caller learns nothing about
  -- whether a case exists anywhere they are not a designee.
  if v_estate is null or not public.is_estate_executor(v_estate, v_uid) then
    raise exception 'not_authorized' using errcode = '42501';
  end if;

  if v_status <> 'open' then
    raise exception 'case_not_open' using errcode = 'P0001';
  end if;

  select d.estate_id into v_doc_estate from public.documents d where d.id = p_document;
  -- One sentinel for missing and foreign alike: a designee cannot probe the document space of
  -- other estates through attachment errors.
  if v_doc_estate is null or v_doc_estate <> v_estate then
    raise exception 'doc_not_in_estate' using errcode = 'P0001';
  end if;

  insert into public.death_verification_evidence (case_id, estate_id, document_id, submitted_by)
  values (p_case, v_estate, p_document, v_uid)
  returning id into v_evidence;

  perform public.write_audit(
    'death_case.evidence_attached', 'death_verification_evidence', v_evidence, v_estate,
    jsonb_build_object('case_id', p_case, 'evidence_id', v_evidence, 'document_id', p_document));
  return v_evidence;
end $function$;
revoke execute on function public.attach_death_verification_evidence(uuid, uuid) from public, anon;
grant  execute on function public.attach_death_verification_evidence(uuid, uuid) to authenticated;

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- cancel_death_verification_case(p_case) → text                            [authenticated, gated]
-- ────────────────────────────────────────────────────────────────────────────────────────────────
--
-- The initiator may withdraw an OPEN case — and only while they still hold an active designation:
-- a revoked fiduciary does not keep acting because a case remembers them. Cancellation returns the
-- lifecycle to `active`; the case row survives as history.
create or replace function public.cancel_death_verification_case(p_case uuid)
 returns text
 language plpgsql
 security definer
 set search_path to 'public'
as $function$
declare
  v_uid          uuid := auth.uid();
  v_estate       uuid;
  v_status       text;
  v_initiated_by uuid;
begin
  if v_uid is null then
    raise exception 'auth_required' using errcode = '42501';
  end if;

  select c.estate_id, c.status, c.initiated_by
    into v_estate, v_status, v_initiated_by
    from public.death_verification_cases c
   where c.id = p_case
   for update;
  if v_estate is null
     or v_initiated_by <> v_uid
     or not public.is_estate_executor(v_estate, v_uid) then
    raise exception 'not_authorized' using errcode = '42501';
  end if;

  if v_status = 'cancelled' then
    return v_status; -- idempotent replay: no re-stamp, no re-audit (the claim-decision precedent)
  end if;
  if v_status <> 'open' then
    raise exception 'case_already_decided' using errcode = 'P0001';
  end if;

  update public.death_verification_cases
     set status = 'cancelled', updated_at = now()
   where id = p_case;

  perform public.apply_estate_lifecycle_transition(v_estate, 'active', p_case, 'case_cancelled');

  perform public.write_audit(
    'death_case.cancelled', 'death_verification_cases', p_case, v_estate,
    jsonb_build_object('case_id', p_case));
  return 'cancelled';
end $function$;
revoke execute on function public.cancel_death_verification_case(uuid) from public, anon;
grant  execute on function public.cancel_death_verification_case(uuid) to authenticated;

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- admin_review_death_evidence(p_evidence, p_outcome, p_note) → text            [admin, AAL2+fresh]
-- ────────────────────────────────────────────────────────────────────────────────────────────────
--
-- Records the platform's review of one received evidence item. The outcome vocabulary says what
-- happened — a reviewer accepted or rejected the item — never that a document is authentic (no
-- vendor exists to say so). Reviewing evidence DOES NOT move the attained level: that is a
-- separate, separately-audited act, so "the file looked right" can never silently become "the
-- death is verified" (T15).
create or replace function public.admin_review_death_evidence(
  p_evidence uuid,
  p_outcome  text,
  p_note     text default null
)
 returns text
 language plpgsql
 security definer
 set search_path to 'public'
as $function$
declare
  v_uid     uuid;
  v_case    uuid;
  v_estate  uuid;
  v_status  text;
begin
  perform public.admin_require_gate();
  v_uid := auth.uid();

  if p_outcome not in ('reviewed_accepted', 'reviewed_rejected') then
    raise exception 'invalid_review_outcome' using errcode = 'P0001';
  end if;

  select e.case_id, e.estate_id, e.review_status
    into v_case, v_estate, v_status
    from public.death_verification_evidence e
   where e.id = p_evidence
   for update;
  if v_case is null then
    raise exception 'evidence_not_found' using errcode = 'P0002';
  end if;

  if v_status = p_outcome then
    return v_status; -- idempotent replay: no re-stamp, no re-audit
  end if;
  if v_status <> 'received' then
    raise exception 'evidence_already_reviewed' using errcode = 'P0001';
  end if;

  update public.death_verification_evidence
     set review_status = p_outcome, reviewed_by = v_uid, reviewed_at = now(), review_note = p_note
   where id = p_evidence;

  -- Direct insert, source='admin', severity high — the admin_decide_claim_packet precedent.
  -- Metadata names ids and the outcome; never document contents, titles, or claimant identity.
  insert into public.audit_logs (actor_id, estate_id, action, target_table, target_id, metadata, source)
  values (v_uid, v_estate, 'death_case.evidence_reviewed', 'death_verification_evidence', p_evidence,
          jsonb_build_object('severity', 'high', 'case_id', v_case,
                            'evidence_id', p_evidence, 'outcome', p_outcome),
          'admin');
  return p_outcome;
end $function$;
revoke execute on function public.admin_review_death_evidence(uuid, text, text) from public, anon;
grant  execute on function public.admin_review_death_evidence(uuid, text, text) to authenticated;

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- admin_set_attained_verification_level(p_case, p_level, p_basis) → text       [admin, AAL2+fresh]
-- ────────────────────────────────────────────────────────────────────────────────────────────────
--
-- ★ THE ONLY WRITER of `attained_level`. The parameter is TYPED to the policy engine's enum, so an
-- out-of-vocabulary level is unrepresentable at the call boundary — it fails Postgres enum
-- decoding before this body runs, and there is no text path around it. NULL is refused: attained
-- never returns to "unknown" by assertion; it starts there and moves only by this audited act.
--
-- Nothing here compares the level to the requirement — attainment is a fact, sufficiency is the
-- DECISION routine's question. And nothing here derives a level from evidence counts: a reviewer
-- states what the review process actually established, with the basis recorded.
create or replace function public.admin_set_attained_verification_level(
  p_case  uuid,
  p_level public.verification_level,
  p_basis text default null
)
 returns text
 language plpgsql
 security definer
 set search_path to 'public'
as $function$
declare
  v_uid    uuid;
  v_estate uuid;
  v_status text;
  v_old    public.verification_level;
begin
  perform public.admin_require_gate();
  v_uid := auth.uid();

  if p_level is null then
    raise exception 'invalid_verification_level' using errcode = 'P0001';
  end if;

  select c.estate_id, c.status, c.attained_level
    into v_estate, v_status, v_old
    from public.death_verification_cases c
   where c.id = p_case
   for update;
  if v_estate is null then
    raise exception 'case_not_found' using errcode = 'P0002';
  end if;
  if v_status <> 'open' then
    raise exception 'case_not_open' using errcode = 'P0001';
  end if;

  if v_old is not distinct from p_level then
    return p_level::text; -- idempotent replay: no re-stamp, no re-audit
  end if;

  update public.death_verification_cases
     set attained_level = p_level, updated_at = now()
   where id = p_case;

  insert into public.audit_logs (actor_id, estate_id, action, target_table, target_id, metadata, source)
  values (v_uid, v_estate, 'death_case.attained_level_set', 'death_verification_cases', p_case,
          jsonb_build_object('severity', 'high', 'case_id', p_case,
                            'old_level', v_old::text, 'new_level', p_level::text,
                            'basis', p_basis),
          'admin');
  return p_level::text;
end $function$;
revoke execute on function public.admin_set_attained_verification_level(uuid, public.verification_level, text)
  from public, anon;
grant  execute on function public.admin_set_attained_verification_level(uuid, public.verification_level, text)
  to authenticated;

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- admin_decide_death_verification_case(p_case, p_decision, p_note) → text      [admin, AAL2+fresh]
-- ────────────────────────────────────────────────────────────────────────────────────────────────
--
-- ★ H2 CLOSED HERE: `verify` refuses unless attained ≥ required, with the requirement RE-DERIVED
-- LIVE from the policy engine at decision time — the initiation snapshot is a record, not the
-- gate. A NULL attained level coalesces to refusal (the three-valued-logic trap, handled the way
-- `release_condition_satisfied` handles it).
--
-- ★ VERIFYING A DEATH RELEASES NOTHING. The lifecycle moves to `death_verified` and that is the
-- entire effect: no grant goes live (`release_condition_satisfied` takes no lifecycle state, and
-- `after_verified_death` satisfies nothing under any policy), no notification is emitted, no
-- claim row changes, no read path consults the new state. The 11-C suite compares every viewer's
-- composed payload across this transition and requires byte identity.
create or replace function public.admin_decide_death_verification_case(
  p_case     uuid,
  p_decision text,
  p_note     text default null
)
 returns text
 language plpgsql
 security definer
 set search_path to 'public'
as $function$
declare
  v_uid      uuid;
  v_estate   uuid;
  v_status   text;
  v_attained public.verification_level;
  v_required public.verification_level;
  v_target   text;
begin
  perform public.admin_require_gate();
  v_uid := auth.uid();

  if p_decision not in ('verify', 'reject') then
    raise exception 'invalid_decision' using errcode = 'P0001';
  end if;
  v_target := case p_decision when 'verify' then 'verified' else 'rejected' end;

  select c.estate_id, c.status, c.attained_level
    into v_estate, v_status, v_attained
    from public.death_verification_cases c
   where c.id = p_case
   for update;
  if v_estate is null then
    raise exception 'case_not_found' using errcode = 'P0002';
  end if;

  if v_status = v_target then
    return v_status; -- idempotent replay: no re-stamp, no re-audit
  end if;
  if v_status <> 'open' then
    raise exception 'case_already_decided' using errcode = 'P0001';
  end if;

  if p_decision = 'verify' then
    -- LIVE requirement, not the snapshot: a policy tightened mid-case tightens the case.
    v_required := public.required_verification_level(v_estate);
    if not coalesce(v_attained >= v_required, false) then
      raise exception 'verification_level_insufficient' using errcode = 'P0001';
    end if;
  end if;

  update public.death_verification_cases
     set status = v_target, decided_by = v_uid, decided_at = now(),
         decision_note = p_note, updated_at = now()
   where id = p_case;

  perform public.apply_estate_lifecycle_transition(
    v_estate,
    case when p_decision = 'verify' then 'death_verified' else 'active' end,
    p_case,
    'case_' || v_target);

  insert into public.audit_logs (actor_id, estate_id, action, target_table, target_id, metadata, source)
  values (v_uid, v_estate, 'death_case.' || v_target, 'death_verification_cases', p_case,
          jsonb_build_object('severity', 'high', 'case_id', p_case, 'decision', p_decision,
                            'required_level', v_required::text, 'attained_level', v_attained::text,
                            'reviewer_id', v_uid),
          'admin');
  return v_target;
end $function$;
revoke execute on function public.admin_decide_death_verification_case(uuid, text, text) from public, anon;
grant  execute on function public.admin_decide_death_verification_case(uuid, text, text) to authenticated;


-- ==== db/functions/release_safety.sql =============================================================
-- ════════════════════════════════════════════════════════════════════════════════════════════════
-- PHASE 11-E · RELEASE SAFETY — the challenge window between death_verified and released
-- ════════════════════════════════════════════════════════════════════════════════════════════════
--
-- ★ WHAT THIS FILE OWNS. The three transitions that stand between an accepted death verification
-- and irreversible disclosure, plus the owner-facing status read:
--
--   begin_challenge_window   death_verified → challenge_window     [admin, AAL2+fresh]
--   challenge_death_process  any pre-released death-process state
--                            → challenge_halted                    [the authenticated OWNER, alone]
--   release_estate           challenge_window → released           [INTERNAL — no reachable door]
--   get_owner_safety_status  owner-scoped presentation union       [authenticated, owner-gated]
--
-- ★ WHAT THIS FILE MUST NEVER TOUCH: access_grants, visibility tiers, memberships, designations,
-- documents, claim rows, or the release predicate. Release is EVALUATIVE — the lifecycle moves and
-- the one canonical predicate answers differently. `test/deathVerificationFoundation.test.ts`
-- pins the forbidden set for this file exactly as it does for the death-verification module.
--
-- ★ THE SAFETY NOTIFICATION IS LOAD-BEARING, AND THE EMITTER'S USUAL TRADE IS INVERTED HERE.
-- `emit_lifecycle_notification` deliberately swallows insert failure so that a grant still commits
-- when a heads-up cannot be written — the right trade for a heads-up. The window-open notice is
-- not a heads-up: it is the owner's one chance to object before disclosure becomes irreversible,
-- so `begin_challenge_window` REQUIRES the emit to return a committed row id and rolls the whole
-- transition back otherwise. The window cannot begin un-notified. (Reliability class, stated
-- honestly: one in-app notification row, committed in the SAME transaction as the transition.
-- Whether that class is sufficient to start a release clock in production is part of the window-
-- duration product decision; until an operator configures a duration, no window can elapse.)
--
-- ★ THE TIEBREAK IS STRUCTURAL (R14). Release requires the window STRICTLY elapsed. At the exact
-- boundary instant the release refuses while the challenge still succeeds; both serialize on the
-- lifecycle row lock; and the transition map has no edge out of challenge_halted, so a committed
-- challenge is final in 11-E — no resume, no admin override (R: deliberately absent, a future
-- product decision).
--
-- ★ PHASE 11-OC / PHASE D MOVED THE ANCHOR THAT THE STRICTNESS APPLIES TO, AND NOTHING ELSE ABOUT
-- IT. The comparison was `now() > owner_notified_at + duration`; it is now
-- `now() > notice_accepted_at + duration`, decided by `owner_notice_release_authority` below.
-- `owner_notified_at` is stamped when the email row is QUEUED, so the seven days used to run while
-- the message sat unsent and kept running when the provider rejected it outright. The seven-day
-- POLICY is unchanged — `challenge_window_duration()` is untouched — only the instant it counts
-- from. There is deliberately no fallback from acceptance to provenance: a coalesce would silently
-- restore the defective clock for exactly the legacy population Phase D exists to refuse.
--
-- ★ CHALLENGE PROVENANCE IS PROTECTED (§17). The audit row records THAT the owner challenged and
-- from which lifecycle state — never a channel, device, address, or location. `write_audit` does
-- not populate ip/user_agent, and nothing here adds them. Claimant-facing surfaces may learn only
-- that the process halted.
--
-- Deploys via `db/bundles/death_verification_bundle.sql` (after 0054 and the workflow routines).
-- Source of truth — re-apply on DB reset.

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- challenge_window_duration() → interval                        [INTERNAL — the configured window]
-- ────────────────────────────────────────────────────────────────────────────────────────────────
--
-- NULL means NOT CONFIGURED, and not configured means the window never elapses (fail-closed:
-- release refuses, the challenge stays available). Read LIVE at release time — the H2 precedent:
-- a duration lengthened mid-window lengthens the window; there is no stamped deadline to go stale.
create or replace function public.challenge_window_duration()
 returns interval
 language sql
 security definer
 stable
 set search_path to 'public'
as $function$
  select p.challenge_window from public.release_safety_policy p where p.id;
$function$;
revoke execute on function public.challenge_window_duration() from public, anon, authenticated;

comment on function public.challenge_window_duration() is
  'The configured owner-challenge window (Phase 11-E). NULL = not configured = the window never '
  'elapses and release refuses. Set only by an explicit, reviewed operator INSERT into '
  'release_safety_policy — never seeded by a migration. INTERNAL: clients cannot read the safety '
  'clock; the owner surface answers through get_owner_safety_status.';

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- dispatch_owner_safety_notice(p_estate) → text                               [admin, AAL2+fresh]
-- ────────────────────────────────────────────────────────────────────────────────────────────────
--
-- ★ PHASE 11-F, D4 — "the owner was told" MUST mean an independently reachable channel. 11-E wrote
-- one in-app notification and required it to commit; that is a real guarantee and it is not enough,
-- because a person who has stopped opening the app is exactly the person a false death process
-- targets successfully. This routine additionally commits an EMAIL row addressed to the owner, in
-- the SAME transaction as the state change, and refuses the whole transition if it cannot.
--
-- ★ THE REQUIREMENT IS DISPATCH INITIATION, NOT DELIVERY (Stage 2, stated exactly). No read
-- receipt, no open tracking, no acknowledgement — none of which this product can honestly observe,
-- and each of which would let a silent mail server hold a release hostage forever. What IS required
-- is that a real address was resolved and a real row was committed to a real queue.
--
-- ★ AND AN UNRESOLVABLE ADDRESS IS A HARD FAILURE. Queueing a row with no recipient would be
-- "dispatch initiated" in name only — the fail-closed answer is to refuse the transition, leaving
-- the estate at `death_verified` where nothing can release, rather than starting a clock nobody can
-- hear ticking.
--
-- ★ D2 — `owner_notified_at` IS STAMPED HERE, AND SINCE PHASE 11-OC / PHASE D IT IS PROVENANCE
-- RATHER THAN THE RELEASE CLOCK. It records the instant the operator initiated dispatch — not claim
-- creation, evidence upload, verification or administrative review, none of which the owner can see
-- — and that remains the right fact for this row to carry. What it is NOT is proof that a message
-- left the building: it is written when the outbox row is QUEUED, before any worker has run. The
-- seven days now run from `notice_accepted_at` on the accepted notice; see
-- `owner_notice_release_authority`. This routine is unchanged by Phase D.
create or replace function public.dispatch_owner_safety_notice(p_estate uuid)
 returns text
 language plpgsql
 security definer
 set search_path to 'public'
as $function$
declare
  v_uid       uuid;
  v_state     text;
  v_owner     uuid;
  v_recipient text;
  v_case      uuid;
  v_notice    uuid;
  v_outbox    uuid;
begin
  perform public.admin_require_gate();
  v_uid := auth.uid();

  select l.state into v_state
    from public.estate_lifecycle l
   where l.estate_id = p_estate
   for update;

  if v_state = 'owner_notification_dispatched' then
    return 'owner_notification_dispatched'; -- idempotent replay: no re-dispatch, no re-audit
  end if;
  if v_state is distinct from 'death_verified' then
    raise exception 'invalid_dispatch_state' using errcode = 'P0001';
  end if;

  select c.id into v_case
    from public.death_verification_cases c
   where c.estate_id = p_estate and c.status = 'verified'
   order by c.decided_at desc
   limit 1;
  if v_case is null then
    raise exception 'no_verified_case' using errcode = 'P0001';
  end if;

  v_owner := public.estate_owner_user_id(p_estate);
  if v_owner is null then
    raise exception 'owner_unresolved' using errcode = 'P0001';
  end if;

  -- ★ THE INDEPENDENT CHANNEL, RESOLVED FROM THE IDENTITY PROVIDER rather than from anything a
  -- claimant can write. `profiles.email` is user-editable in principle; `auth.users.email` is the
  -- address the account authenticates with, which is the one a claimant cannot repoint.
  select u.email into v_recipient from auth.users u where u.id = v_owner;
  if v_recipient is null or btrim(v_recipient) = '' then
    raise exception 'owner_channel_unreachable' using errcode = 'P0001';
  end if;

  -- EMAIL FIRST: the row whose existence is the dispatch. Same transaction as the transition, so a
  -- rollback anywhere below un-dispatches it and the window never opened.
  -- ★ PHASE 11-OC — THE ROW NAMES ITS EPISODE, AND `v_case` WAS ALREADY IN HAND.
  --
  -- `v_case` is resolved above and, until this phase, was discarded into the audit metadata only. It
  -- is the EPISODE key: one estate may legitimately experience several independent death processes
  -- over time (`rejected` and `cancelled` both return the lifecycle to `active`), so an accepted
  -- notice from a prior, rejected process must never authorize a release under a later case. Scoping
  -- the release predicate to the estate would do exactly that; scoping it to the case cannot.
  --
  -- `generation` is the literal 1 here and only ever incremented by the re-notice routine, under the
  -- predecessor's row lock — never from an unlocked max().
  --
  -- A BEFORE INSERT trigger (migration 0058) refuses any owner-notice row with a NULL case_id, so
  -- this is a wall rather than a promise this routine makes. Legacy rows keep their NULL and stay
  -- updatable, because the trigger fires on INSERT only.
  insert into public.owner_notice_outbox
    (estate_id, user_id, channel, recipient, notice_kind, status, case_id, generation)
  values (p_estate, v_owner, 'email', v_recipient, 'death_process.window_opened', 'queued',
          v_case, 1)
  returning id into v_outbox;
  if v_outbox is null then
    raise exception 'owner_notification_failed' using errcode = 'P0001';
  end if;

  -- IN-APP SECOND, and still REQUIRED (11-E's guarantee is kept, not replaced). Two channels, both
  -- committed, before any clock starts.
  v_notice := public.emit_lifecycle_notification(
    v_owner, p_estate, 'death_process.window_opened', 'afterworth://challenge');
  if v_notice is null then
    raise exception 'owner_notification_failed' using errcode = 'P0001';
  end if;

  perform public.apply_estate_lifecycle_transition(
    p_estate, 'owner_notification_dispatched', v_case, 'owner_notice_dispatched');

  update public.estate_lifecycle
     set owner_notified_at = now(),
         safety_notification_id = v_notice
   where estate_id = p_estate;

  -- ★ THE AUDIT RECORDS THE CHANNEL CLASS, NEVER THE ADDRESS. That a notice went to email is an
  -- operational fact; WHICH address is a living owner's contact detail, and an audit row outlives
  -- every reason anyone had to read it.
  insert into public.audit_logs (actor_id, estate_id, action, target_table, target_id, metadata, source)
  values (v_uid, p_estate, 'death_process.owner_notice_dispatched', 'owner_notice_outbox', v_outbox,
          jsonb_build_object('severity', 'high', 'case_id', v_case, 'channel', 'email',
                            'in_app_notification_id', v_notice),
          'admin');
  return 'owner_notification_dispatched';
end $function$;
revoke execute on function public.dispatch_owner_safety_notice(uuid) from public, anon;
grant  execute on function public.dispatch_owner_safety_notice(uuid) to authenticated;

comment on function public.dispatch_owner_safety_notice(uuid) is
  'Phase 11-F (D4): commits an EMAIL row and an in-app notice to the owner, in the same transaction '
  'as the death_verified -> owner_notification_dispatched transition, and stamps owner_notified_at '
  '(D2: the challenge clock starts at dispatch). Requires dispatch INITIATION, never delivery '
  'confirmation. An unresolvable owner address refuses the transition. Admin-gated; idempotent.';

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- owner_notice_release_authority(p_case) → jsonb                                       [INTERNAL]
-- ────────────────────────────────────────────────────────────────────────────────────────────────
--
-- ★ PHASE 11-OC · PHASE D — THE ONE PLACE THE RELEASE DOOR'S OWNER-NOTICE AUTHORITY IS DECIDED.
--
-- Before this phase, `authorize_release` asked TWO questions in two places and got the wrong answer
-- to both. It asked "does an email row exist for this ESTATE with `status <> 'cancelled'`" — a
-- predicate nothing in production can falsify, because `dispatch_owner_safety_notice` inserts that
-- row in the same transaction as the transition and no production path ever writes `'cancelled'`.
-- And it measured the seven days from `owner_notified_at`, which is stamped when the row is QUEUED:
-- the clock ran while the message sat unsent, and kept running when the provider rejected it.
--
-- Phase D replaces both with ONE fact the database can actually prove:
--
--        THE CURRENT GENERATION OF THE CURRENT CASE EPISODE HAS `notice_accepted_at`.
--
-- ★ WHAT THAT FACT IS, AND WHAT IT IS NOT — stated here because this is the last place anybody
-- reads before trusting it. `notice_accepted_at` is stamped by exactly one branch of exactly one
-- routine (`record_owner_notice_outcome`, `providerAccepted`). It means the EMAIL PROVIDER ACCEPTED
-- THE MESSAGE FOR DELIVERY. It is **not** delivered, not received, not opened, not read, and no
-- caller, projection, console label or document may rename it into any of those. It is the
-- strongest persisted provider fact this system currently has, and Phase D protects on that rather
-- than on a weaker one — never on a stronger one it cannot observe.
--
-- ★ IT IS A SEPARATE FUNCTION FOR THE `owner_notice_reissue_assessment` REASON, WHICH IS NOT
-- TIDINESS. Three callers need this verdict: the release door, the operator case file, and the
-- deployment verifier. A second opinion in any of them — a status list in a projection, a `case`
-- expression in the case file, a TypeScript mirror in the console — is a policy that drifts, and
-- the failure mode is an operator being offered a release the server refuses, or (far worse) a
-- console that says READY while the door's own rule says otherwise. So the door and the projection
-- call the SAME function, and `db/tests/release_safety_authorization.sql` §12 asserts they agree on
-- every fixture rather than assuming they must.
--
-- ★ FOUR INDEPENDENT AUTHORITIES, AND EVERY ONE OF THEM MUST HOLD.
--
--   1. EPISODE  — the notice must belong to the CURRENT death-verification case (D3). One estate may
--                 legitimately run several death processes over time: `rejected` and `cancelled`
--                 both return the lifecycle to `active`, and a later case opens a new episode. An
--                 accepted notice from a PRIOR, REJECTED process authorizing a release under a NEW
--                 case is the estate-scope defect this whole phase exists to close. The canonical
--                 case is re-resolved HERE from the estate and the caller's `p_case` is compared
--                 against it — never trusted as the episode.
--
--   2. GENERATION — the notice must be the STRUCTURALLY current generation (D4): the row nothing
--                 supersedes. `superseded_by is null`, which is a partial-unique-indexed wall, not
--                 `max(generation)`, not `max(requested_at)`, not "the newest timestamp", not array
--                 order. A derived-max invariant cannot be expressed as a constraint, so a door
--                 resting on one rests on an invariant only the writer maintains.
--
--   3. ACCEPTANCE — `notice_accepted_at is not null` on that row (D1). NOT `status = 'dispatched'`,
--                 NOT `status <> 'cancelled'`, NOT a status allow-list of any shape. The authority
--                 is VOCABULARY-INDEPENDENT on purpose: a seventh status added to the CHECK
--                 constraint tomorrow must not become release-qualifying merely by not being
--                 `'cancelled'`, and it cannot, because no status string appears in this decision.
--
--   4. CLOCK   — `now() > notice_accepted_at + challenge_window_duration()`, STRICTLY (D5). At the
--                 exact boundary instant this refuses and the owner's challenge — serialized on the
--                 same lifecycle row lock — still succeeds. `owner_notified_at` is PROVENANCE and is
--                 never the anchor; there is deliberately no `coalesce` from one to the other,
--                 because a fallback would silently restore the defective clock for exactly the
--                 legacy population Phase D exists to refuse.
--
-- ★ CURRENT-GENERATION-ONLY AND EPISODE-EXISTENTIAL AGREE ON EVERY REACHABLE STATE, AND THAT WAS
-- PROVEN BY READING THE SETTLE PATH RATHER THAN ASSUMED. `owner_notice_release_readiness_census`
-- reads acceptance as an existential over the whole episode, and argues — correctly — that
-- authority must be MONOTONE: if issuing a re-notice could REMOVE release authority, an operator
-- would hold a lever that suppresses a release. This function reads only the current generation,
-- which looks like it breaks that property. It does not, and the reason is structural:
--
--   · `record_owner_notice_outcome` no-ops on any row already `dispatched`, `outcomeUncertain`,
--     `failedPermanent` or `cancelled`, so a settled row can never gain an acceptance stamp.
--   · `owner_notice_reissue_assessment` permits a re-notice ONLY when the current generation is
--     `failedPermanent`, `outcomeUncertain`, or `dispatched` with NULL acceptance — all settled,
--     all NULL-acceptance at the instant of supersession. `queued` and `processing` (the only rows
--     that can still gain acceptance) are refused, so they are never superseded.
--
-- Therefore a superseded row carrying `notice_accepted_at` is UNREACHABLE through the deployed
-- doors, the two readings can differ only on a state the system cannot produce, and reading the
-- current generation costs no monotonicity. It is nevertheless read strictly, because D4 asks for
-- the structural invariant rather than for an argument that the loose one happens to be safe — and
-- §12 mutation-proves that a hand-written superseded acceptance authorizes NOTHING.
--
-- ★ IT FAILS CLOSED, AND EVERY REFUSAL HAS A NAME FROM A CLOSED SET. There is no fall-through: a
-- state this ladder does not recognise lands on an explicit code rather than joining a neighbouring
-- branch. `notice_never_accepted` is deliberately NOT called `notice_not_delivered` — mailbox
-- delivery is not known to this system and naming it would be the console inventing the one fact
-- this phase exists to stop being invented.
--
-- ★ IT DISCLOSES NO IDENTITY. No recipient address, no owner user id, no estate name, no provider
-- secret. Row ids, a generation number, two timestamps and a code — the facts an operator needs to
-- know whether a release call will be refused, and nothing that describes a living person.
create or replace function public.owner_notice_release_authority(p_case uuid)
 returns jsonb
 language plpgsql
 security definer
 stable
 set search_path to 'public'
as $function$
declare
  v_c         public.death_verification_cases%rowtype;
  v_state     text;
  v_canonical uuid;
  v_row       public.owner_notice_outbox%rowtype;
  v_duration  interval;
  v_eligible  timestamptz;
  v_elapsed   boolean := false;
  v_refusal   text;
begin
  if p_case is null then
    return jsonb_build_object('ready', false, 'refusal_code', 'case_not_found',
                              'window_configured', false, 'elapsed', false);
  end if;

  select * into v_c from public.death_verification_cases c where c.id = p_case;
  if not found then
    return jsonb_build_object('ready', false, 'refusal_code', 'case_not_found',
                              'window_configured', false, 'elapsed', false);
  end if;

  -- AUTHORITY 1 · THE EPISODE. Resolved canonically from the ESTATE and compared against the
  -- caller's case — the identical derivation `authorize_release`, `dispatch_owner_safety_notice`,
  -- `owner_notice_reissue_assessment` and the readiness census all use. A caller cannot nominate an
  -- episode, so a historical case cannot be handed in as if it were current.
  select c.id into v_canonical
    from public.death_verification_cases c
   where c.estate_id = v_c.estate_id and c.status = 'verified'
   order by c.decided_at desc
   limit 1;

  select l.state into v_state from public.estate_lifecycle l where l.estate_id = v_c.estate_id;
  v_state := coalesce(v_state, 'active');

  -- AUTHORITY 2 · THE CURRENT GENERATION. Structural — `superseded_by is null` — never a max().
  -- The kind SET comes from `owner_notice_episode_kinds()` rather than a literal, for the reason
  -- Phase C gives: a literal here could not see a re-notice, so a remediated estate would be
  -- refused by the door that its remedy was built to unblock.
  select * into v_row
    from public.owner_notice_outbox o
   where o.case_id = p_case
     and o.channel = 'email'
     and o.notice_kind = any (public.owner_notice_episode_kinds())
     and o.superseded_by is null
   limit 1;

  v_duration := public.challenge_window_duration();

  -- AUTHORITY 4 · THE CLOCK, computed before the ladder so the projection can render the facts even
  -- on a branch that refuses. STRICT `>`; the coalesce is the three-valued-logic discipline — a NULL
  -- comparison must refuse, not pass.
  if v_row.notice_accepted_at is not null and v_duration is not null then
    v_eligible := v_row.notice_accepted_at + v_duration;
    v_elapsed  := coalesce(now() > v_eligible, false);
  end if;

  -- ── THE REFUSAL LADDER, IN THE ORDER THE DOOR APPLIES IT ─────────────────────────────────────
  if v_canonical is null then
    v_refusal := 'no_verified_case';
  elsif v_canonical <> p_case then
    -- A historical case on an estate that has moved on, or a case that was never verified. Either
    -- way the accepted notice it may carry authorizes NOTHING under the current process.
    v_refusal := 'notice_episode_mismatch';
  elsif v_state is distinct from 'challenge_window' then
    -- The release door's own state guard, restated here so the projection refuses for the same
    -- reason the routine will. `challenge_halted` lands here: release can never proceed from a halt.
    v_refusal := 'invalid_release_state';
  elsif v_row.id is null then
    -- No notice names this episode at all. Fail closed: an estate with no provable notice is not an
    -- estate whose owner was warned. Pre-Phase-A rows carry a NULL case_id and land here by design —
    -- they belong to no provable episode and are never guessed into one.
    v_refusal := 'no_current_notice';
  elsif v_row.notice_accepted_at is null then
    -- AUTHORITY 3 · THE LEGACY / UNSETTLED CLASS (D6). Covers every non-accepted shape at once and
    -- WITHOUT consulting a status string: `queued` (never sent), `processing` (never settled),
    -- `outcomeUncertain` (unknown), `failedPermanent` (definitively failed), `cancelled`, a
    -- pre-Phase-A `dispatched` row whose stamp did not exist, and any seventh status a future CHECK
    -- constraint admits. The remedy is a Phase C re-notice that PRODUCES the fact, never a backfill
    -- that invents one and never a manual UPDATE of a safety table.
    v_refusal := 'notice_never_accepted';
  elsif v_duration is null then
    -- NULL duration means NOT CONFIGURED, which means the window never elapses and release refuses.
    v_refusal := 'release_window_not_configured';
  elsif not v_elapsed then
    v_refusal := 'release_window_not_elapsed';
  end if;

  return jsonb_build_object(
    'ready',               v_refusal is null,
    'refusal_code',        v_refusal,
    'case_id',             p_case,
    'case_is_current',     v_canonical is not null and v_canonical = p_case,
    'lifecycle_state',     v_state,
    'notice_id',           v_row.id,
    'generation',          v_row.generation,
    'notice_kind',         v_row.notice_kind,
    -- THE FACT. NULL is a real answer and every consumer must render it as one.
    'notice_accepted_at',  v_row.notice_accepted_at,
    'accepted',            v_row.id is not null and v_row.notice_accepted_at is not null,
    'window_duration',     v_duration::text,
    'window_configured',   v_duration is not null,
    -- Anchored on ACCEPTANCE, never on owner_notified_at. NULL until there is an acceptance fact to
    -- anchor on, which is the honest answer rather than a date computed from provenance.
    'release_eligible_at', v_eligible,
    'elapsed',             v_elapsed);
end $function$;
revoke execute on function public.owner_notice_release_authority(uuid)
  from public, anon, authenticated;

comment on function public.owner_notice_release_authority(uuid) is
  'THE owner-notice release authority (Phase 11-OC / Phase D), consumed by both authorize_release '
  'and the operator case-file projection so the console can never offer a release the door refuses. '
  'A release qualifies ONLY when the CURRENT generation (superseded_by is null) of the CURRENT case '
  'episode carries notice_accepted_at, and now() > that instant + challenge_window_duration() '
  'STRICTLY. No status string participates in the decision, so a future status cannot become '
  'release-qualifying by not being cancelled. notice_accepted_at is PROVIDER ACCEPTANCE and never '
  'mailbox delivery; owner_notified_at is provenance and is never the clock. Every refusal carries '
  'a NAMED code from a closed set. Discloses no address and no identity. INTERNAL.';

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- begin_challenge_window(p_estate) → text                                      [admin, AAL2+fresh]
-- ────────────────────────────────────────────────────────────────────────────────────────────────
--
-- ★ REWRITTEN IN 11-F: it no longer notifies, because it no longer can. The notice moved to
-- `dispatch_owner_safety_notice`, and the edge `death_verified → challenge_window` was DELETED from
-- the transition map — so this routine's only legal input is an estate whose owner has already been
-- sent an email and an in-app notice. The guarantee "no window opens un-notified" is now carried by
-- the state machine rather than by this function remembering to check.
--
-- ★ PHASE D CORRECTS ITS INERT PREDICATE AND DELIBERATELY DOES **NOT** IMPORT THE RELEASE POLICY.
--
-- This door used to ask for an email row on the ESTATE with `status <> 'cancelled'` — the same
-- vacuous test the release door carried, and inert for the same reason. Phase D replaces it with
-- the fact it actually needs: A COMMITTED OWNER-SAFETY EMAIL NOTICE EXISTS FOR THE CURRENT CASE
-- EPISODE. Case-scoped, so an accepted notice from a PRIOR death process cannot satisfy it; the
-- current generation, so the check anchors on the same structural invariant the release door uses.
--
-- ★ AND IT MUST NOT REQUIRE `notice_accepted_at` (D7). Opening the window releases NOTHING — no
-- grant activates, no tier changes, no document becomes readable; the lifecycle moves and the
-- owner's challenge becomes available. The initial notice is normally still `queued` at this instant
-- because the drain runs asynchronously, so requiring provider acceptance here would make the window
-- unopenable until a worker had run, and would gate the owner's own protection on an email provider.
-- The irreversible door is `authorize_release`, and that is the one Phase D tightens.
create or replace function public.begin_challenge_window(p_estate uuid)
 returns text
 language plpgsql
 security definer
 set search_path to 'public'
as $function$
declare
  v_uid   uuid;
  v_state text;
  v_case  uuid;
  v_row   public.estate_lifecycle%rowtype;
begin
  perform public.admin_require_gate();
  v_uid := auth.uid();

  select l.* into v_row
    from public.estate_lifecycle l
   where l.estate_id = p_estate
   for update;
  v_state := v_row.state;

  if v_state = 'challenge_window' then
    return 'challenge_window'; -- idempotent replay
  end if;
  if v_state is distinct from 'owner_notification_dispatched' then
    raise exception 'invalid_window_state' using errcode = 'P0001';
  end if;

  -- Belt beside the state machine: the dispatch facts must actually be on the row.
  if v_row.owner_notified_at is null or v_row.safety_notification_id is null then
    raise exception 'owner_not_notified' using errcode = 'P0001';
  end if;

  -- ★ THE EPISODE IS RESOLVED BEFORE THE NOTICE IS LOOKED FOR, AND THAT ORDER IS THE FIX. The
  -- pre-Phase-D body checked the outbox by ESTATE and resolved the case afterwards, so a notice
  -- belonging to any death process this estate had ever run satisfied the guard.
  select c.id into v_case
    from public.death_verification_cases c
   where c.estate_id = p_estate and c.status = 'verified'
   order by c.decided_at desc
   limit 1;
  if v_case is null then
    raise exception 'no_verified_case' using errcode = 'P0001';
  end if;

  -- ★ PHASE D (D7) — A COMMITTED EMAIL NOTICE FOR **THIS** EPISODE, AND NOTHING STRONGER.
  --
  -- Case-scoped, so a notice from a prior rejected process cannot open a window under a new case.
  -- Current generation (`superseded_by is null`), so this anchors on the same structural invariant
  -- the release door uses — and, because supersession always writes a successor, "a current
  -- generation exists" is equivalent to "any generation exists" for the episode. NO status string
  -- and NO `notice_accepted_at`: the initial dispatch is normally still `queued` at this instant
  -- (the drain is asynchronous), and gating the owner's own protection on a provider would be a
  -- release-door policy applied to a door that discloses nothing.
  if not exists (
    select 1 from public.owner_notice_outbox o
     where o.case_id = v_case
       and o.channel = 'email'
       and o.notice_kind = any (public.owner_notice_episode_kinds())
       and o.superseded_by is null
  ) then
    raise exception 'no_current_notice' using errcode = 'P0001';
  end if;

  perform public.apply_estate_lifecycle_transition(
    p_estate, 'challenge_window', v_case, 'window_opened');

  update public.estate_lifecycle
     set challenge_window_started_at = now()
   where estate_id = p_estate;

  insert into public.audit_logs (actor_id, estate_id, action, target_table, target_id, metadata, source)
  values (v_uid, p_estate, 'death_process.window_opened', 'estate_lifecycle', v_case,
          jsonb_build_object('severity', 'high', 'case_id', v_case,
                            'owner_notified_at', v_row.owner_notified_at),
          'admin');
  return 'challenge_window';
end $function$;
revoke execute on function public.begin_challenge_window(uuid) from public, anon;
grant  execute on function public.begin_challenge_window(uuid) to authenticated;

comment on function public.begin_challenge_window(uuid) is
  'Opens the owner-challenge window (Phase 11-E, rewritten 11-F, re-scoped 11-OC/D). Its ONLY legal '
  'input is owner_notification_dispatched — the death_verified -> challenge_window edge was deleted, '
  'so a window cannot open on an un-notified owner even by mistake. Phase D replaced the inert '
  'estate-scoped status <> cancelled predicate with the fact it needs: a committed email notice for '
  'the CURRENT case episode (no_current_notice otherwise). It deliberately does NOT require '
  'notice_accepted_at — opening the window discloses nothing and the initial notice is normally '
  'still queued. Admin-gated; idempotent; discloses nothing.';

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- authorize_release(p_estate, p_reason) → text                                 [admin, AAL2+fresh]
-- ────────────────────────────────────────────────────────────────────────────────────────────────
--
-- ★ THE TWO-PERSON RULE (D1), AND WHY IT LIVES IN THE DATABASE. The operator who verified the death
-- may not authorize the release. A console can enforce that and a console can be bypassed — by a
-- direct RPC, a future admin tool, a script, or the next rewrite. Here the rule is enforced twice on
-- purpose: this routine refuses, AND `release_authorizations` carries a CHECK constraint that makes
-- a single-reviewer row unwritable by ANY path. The routine is the door; the constraint is the wall.
--
-- ★ reviewer_a IS DERIVED, NEVER SUPPLIED. It is read from the verified case's `decided_by` — the
-- operator who actually made the call. A parameter would let the caller nominate a different
-- "first reviewer" and satisfy the rule against someone who never reviewed anything.
--
-- ★ THIS ROUTINE REPLACES 11-E's `release_estate`, WHICH IS DROPPED BY 0055. Leaving a one-person
-- lever beside a two-person door would be the whole decision undone by an un-rewired caller.
--
-- ★ AND IT STILL MANUFACTURES NOTHING (D5). No grant, no tier, no membership, no designation. The
-- lifecycle moves and the ONE canonical predicate answers differently for grants the owner already
-- authored.
--
-- ════════════════════════════════════════════════════════════════════════════════════════════════
-- ★ PHASE 11-OC / PHASE D — THE OWNER-NOTICE CUTOVER. WHAT CHANGED, AND WHAT DELIBERATELY DID NOT.
-- ════════════════════════════════════════════════════════════════════════════════════════════════
--
-- EXACTLY TWO defective semantics are replaced, and every other guard in this routine is preserved
-- verbatim. Phase D makes release STRICTLY HARDER on every path and easier on none.
--
--   REPLACED · the owner-notice precondition
--       was:  an email row on this ESTATE with `status <> 'cancelled'`
--       now:  `owner_notice_release_authority(v_case)` — the CURRENT generation of the CURRENT
--             episode carries `notice_accepted_at`
--
--   REPLACED · the release clock anchor
--       was:  `now() > owner_notified_at + duration`   (stamped when the row was QUEUED)
--       now:  `now() > notice_accepted_at + duration`  (stamped when the PROVIDER ACCEPTED it)
--
--   PRESERVED · admin gate · non-blank reason · idempotent `released` replay · lifecycle must be
--   `challenge_window` · `owner_notified_at`/`safety_notification_id` present (now PROVENANCE, and
--   kept precisely because Phase D must not make any path easier) · verified-case requirement ·
--   reviewer_a DERIVED from the case decider · reviewer_b distinct · the `release_authorizations`
--   CHECK constraint · live `challenge_window_duration()` · STRICT `>` · the audit row · the
--   transition to `released`.
--
-- ★ THE REFUSAL ORDER IS UNCHANGED FOR EVERY PRE-EXISTING SENTINEL. `invalid_release_state`,
-- `owner_not_notified`, `no_verified_case`, `reviewer_a_unresolved` and `two_person_rule_violated`
-- all still fire before any clock or notice question, in that order, so a caller that was refused
-- for one of those reasons before is refused for the same reason now. The acceptance authority
-- occupies exactly the position the old `owner_channel_unreachable` predicate held relative to the
-- clock: after the two-person rule, before the release is written.
--
-- ★ THE AUTHORITY IS CONSULTED, NEVER RESTATED. This routine contains no status list, no
-- `superseded_by` test, no `case_id` join and no clock arithmetic of its own — all four live in
-- `owner_notice_release_authority`, which the operator console reads through the SAME function. A
-- second copy here is how a door and a console come to disagree in front of an operator holding an
-- irreversible lever.
create or replace function public.authorize_release(p_estate uuid, p_reason text)
 returns text
 language plpgsql
 security definer
 set search_path to 'public'
as $function$
declare
  v_row        public.estate_lifecycle%rowtype;
  v_uid        uuid;
  v_case       uuid;
  v_reviewer_a uuid;
  v_verified   timestamptz;
  v_duration   interval;
  v_auth       jsonb;
begin
  perform public.admin_require_gate();
  v_uid := auth.uid();

  if p_reason is null or btrim(p_reason) = '' then
    raise exception 'audit_reason_required' using errcode = 'P0001';
  end if;

  select l.* into v_row
    from public.estate_lifecycle l
   where l.estate_id = p_estate
   for update;

  if v_row.state = 'released' then
    return 'released'; -- idempotent replay: no second authorization row, no re-audit
  end if;
  if v_row.state is distinct from 'challenge_window' then
    -- challenge_halted lands here too: release can NEVER proceed from a halted process.
    raise exception 'invalid_release_state' using errcode = 'P0001';
  end if;

  -- The dispatch facts (D4), KEPT IN PHASE D AS PROVENANCE. These no longer decide when a release
  -- may proceed — `owner_notice_release_authority` does — but removing them would make one path
  -- easier, and Phase D makes no path easier. A window whose lifecycle row cannot even name the
  -- dispatch that opened it cannot elapse into disclosure.
  if v_row.owner_notified_at is null or v_row.safety_notification_id is null then
    raise exception 'owner_not_notified' using errcode = 'P0001';
  end if;

  select c.id, c.decided_by, c.decided_at into v_case, v_reviewer_a, v_verified
    from public.death_verification_cases c
   where c.estate_id = p_estate and c.status = 'verified'
   order by c.decided_at desc
   limit 1;
  if v_case is null then
    raise exception 'no_verified_case' using errcode = 'P0001';
  end if;
  if v_reviewer_a is null then
    raise exception 'reviewer_a_unresolved' using errcode = 'P0001';
  end if;

  -- ★ D1, ENFORCED HERE AND AGAIN BY THE TABLE CONSTRAINT BELOW.
  if v_uid = v_reviewer_a then
    raise exception 'two_person_rule_violated' using errcode = 'P0001';
  end if;

  -- ════════════════════════════════════════════════════════════════════════════════════════════
  -- ★ PHASE D — THE OWNER-NOTICE ACCEPTANCE AUTHORITY AND THE RELEASE CLOCK, IN ONE CONSULTATION.
  -- ════════════════════════════════════════════════════════════════════════════════════════════
  --
  -- The verdict is read under the lifecycle row lock taken above, so the state it describes cannot
  -- move between the answer and the write. `owner_notice_release_authority` is `stable` — it reads
  -- the calling statement's snapshot — which is correct here for exactly that reason, and is the
  -- same contract `reissue_owner_safety_notice` has with `owner_notice_reissue_assessment`.
  --
  -- ★ THE REFUSAL CODE IS RAISED VERBATIM, NEVER TRANSLATED. A `case` expression mapping the
  -- authority's codes onto this routine's own sentinels would be a second policy: the console reads
  -- the authority directly, so a translation layer here is precisely how the two come to describe
  -- the same estate differently. `release_window_not_configured` and `release_window_not_elapsed`
  -- are therefore still the strings a caller sees — they are now the AUTHORITY's names for them.
  v_auth := public.owner_notice_release_authority(v_case);
  if not (v_auth ->> 'ready')::boolean then
    raise exception '%', v_auth ->> 'refusal_code' using errcode = 'P0001';
  end if;
  -- Read back for the audit, from the SAME verdict that authorized this release rather than from a
  -- second lookup that could describe a different row.
  v_duration := (v_auth ->> 'window_duration')::interval;

  insert into public.release_authorizations
    (estate_id, case_id, reviewer_a, reviewer_b, verified_at, authorized_at, released_at, audit_reason)
  values (p_estate, v_case, v_reviewer_a, v_uid, v_verified, now(), now(), p_reason);

  perform public.apply_estate_lifecycle_transition(
    p_estate, 'released', v_case, 'two_person_release');

  update public.estate_lifecycle
     set released_at = now()
   where estate_id = p_estate;

  insert into public.audit_logs (actor_id, estate_id, action, target_table, target_id, metadata, source)
  values (v_uid, p_estate, 'death_process.released', 'release_authorizations', v_case,
          jsonb_build_object('severity', 'high', 'case_id', v_case,
                            'reviewer_a', v_reviewer_a, 'reviewer_b', v_uid,
                            'verified_at', v_verified,
                            -- PROVENANCE, and labelled as such. It is no longer the clock, and an
                            -- investigator reconstructing a disputed release a year later must be
                            -- able to see which instant the seven days actually ran from.
                            'owner_notified_at', v_row.owner_notified_at,
                            -- ★ THE FACT THE RELEASE RESTED ON, and the two derived instants, taken
                            -- from the verdict that authorized it. Provider acceptance — never
                            -- delivery, and the key name says so.
                            'notice_accepted_at', v_auth ->> 'notice_accepted_at',
                            'release_eligible_at', v_auth ->> 'release_eligible_at',
                            'notice_id', v_auth ->> 'notice_id',
                            'notice_generation', v_auth ->> 'generation',
                            'window_duration', v_duration::text,
                            'audit_reason', p_reason),
          'admin');
  return 'released';
end $function$;
revoke execute on function public.authorize_release(uuid, text) from public, anon;
grant  execute on function public.authorize_release(uuid, text) to authenticated;

comment on function public.authorize_release(uuid, text) is
  'THE release transition (Phase 11-F, re-anchored 11-OC/D): challenge_window -> released, by a '
  'SECOND platform operator. Requires admin gate, a non-empty audit reason, the dispatch provenance '
  'on the lifecycle row, a verified case, reviewer_b <> reviewer_a where reviewer_a is DERIVED from '
  'the case decider, and — from Phase D — owner_notice_release_authority: the CURRENT generation of '
  'the CURRENT case episode must carry notice_accepted_at (PROVIDER ACCEPTANCE, never mailbox '
  'delivery) and the window must be STRICTLY elapsed from THAT instant, not from owner_notified_at. '
  'No status string participates. Ties go to the owner challenge. Records a release_authorizations '
  'row whose CHECK constraint makes a single-reviewer release unwritable by any path. Creates no '
  'grant, tier, membership or designation.';

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- challenge_death_process(p_estate) → text                          [the authenticated OWNER only]
-- ────────────────────────────────────────────────────────────────────────────────────────────────
--
-- ★ R13 IS THE SIGNATURE: one argument, one action. No evidence parameter exists, no review step
-- exists, no waiting period exists, no designation is consulted. The authenticated owner of the
-- estate halts the process — from pending, from death_verified, or from inside the window — and
-- challenge_halted is terminal in 11-E: the map has no edge out, and no routine reopens it.
--
-- ★ THE GATE RUNS BEFORE ANY EXISTENCE OR STATE LOOKUP. `is_estate_owner` answers false for a
-- nonexistent estate and a foreign one alike, so every unauthorized caller — beneficiary,
-- designee, claimant, foreign owner, probe against a random uuid — refuses with the same bytes.
create or replace function public.challenge_death_process(p_estate uuid)
 returns text
 language plpgsql
 security definer
 set search_path to 'public'
as $function$
declare
  v_uid       uuid := auth.uid();
  v_state     text;
  -- ★ Phase 11-L. The initiator of the case THIS CALL halts, captured from the UPDATE's own
  -- RETURNING rather than looked up afterwards. A separate SELECT could name a case this call did
  -- not touch — one already halted, or one halted by a concurrent transaction — and would notify
  -- someone about a process that is still running, or notify twice about one that stopped once.
  v_initiator uuid;
begin
  if v_uid is null then
    raise exception 'auth_required' using errcode = '42501';
  end if;
  if not public.is_estate_owner(p_estate) then
    raise exception 'not_authorized' using errcode = '42501';
  end if;

  select l.state into v_state
    from public.estate_lifecycle l
   where l.estate_id = p_estate
   for update;
  if v_state is null then
    v_state := 'active';
  end if;

  if v_state = 'challenge_halted' then
    return 'challenge_halted'; -- idempotent replay: no re-stamp, no re-audit
  end if;
  if v_state = 'active' then
    raise exception 'nothing_to_challenge' using errcode = 'P0001';
  end if;
  -- Too late is stated honestly (R15): what was disclosed cannot be undisclosed, and pretending
  -- a halt succeeded would claim otherwise. The owner is authorized to know this about their
  -- own estate.
  if v_state = 'released' then
    raise exception 'already_released' using errcode = 'P0001';
  end if;

  perform public.apply_estate_lifecycle_transition(
    p_estate, 'challenge_halted', null, 'owner_challenge');

  update public.estate_lifecycle
     set halted_at = now()
   where estate_id = p_estate;

  -- The live case is halted — distinct from 'cancelled' (initiator withdrew): the owner said no.
  --
  -- ★ PHASE 11-NR — THE SET IS ('open','verified'), AND 'open' ALONE WAS THE DEFECT. This predicate
  -- read `status = 'open'`, which is the case status at exactly ONE of the four lifecycle states this
  -- routine can be reached from. The Branch A production drill measured the consequence: on the
  -- canonical operator-driven path the estate reached challenge_halted while its case row stayed
  -- 'verified', `v_initiator` came back NULL, and the 11-L halt notification — the entire deliverable
  -- of that phase — was never emitted to anybody. The case also stayed in the operator's `verified`
  -- work queue, invisible to a `halted` filter, with the queue row stating the contradiction outright.
  --
  -- The set is CLOSED and derived from the transition map, never "every row for this estate":
  --
  --   death_verification_pending    → case is 'open'      (initiate)
  --   death_verified                → case is 'verified'  (admin_decide 'verify')
  --   owner_notification_dispatched → case is 'verified'  (dispatch requires a verified case)
  --   challenge_window              → case is 'verified'  (begin_challenge_window requires one)
  --
  -- 'rejected' and 'cancelled' both return the lifecycle to `active`, where this routine has already
  -- raised `nothing_to_challenge` — they are decided history and settling them would overwrite an
  -- adjudication that did happen. 'halted' is excluded as a SECOND, independent guard against a
  -- re-stamp: the idempotent return above already refuses to reach this statement.
  --
  -- ★ AND IT STILL MATCHES AT MOST ONE ROW, WHICH NO LONGER FOLLOWS FROM THE INDEX ALONE.
  -- `death_verification_cases_one_open_per_estate` makes 'open' unique per estate; 'verified' is
  -- unique per estate for a different reason, and it is the state machine that supplies it. A
  -- verified case pins the lifecycle at death_verified or beyond, `initiate_death_verification_case`
  -- refuses unless the lifecycle is `active`, and no edge returns there from death_verified — so a
  -- second case cannot be opened once one is verified, and an 'open' case cannot coexist with a
  -- 'verified' one. Historical 'rejected' / 'cancelled' rows DO coexist and are excluded by the
  -- predicate. `into` therefore still has no set to choose from arbitrarily, and
  -- `release_safety_authorization.sql` §8 proves it on an estate that actually carries a decided
  -- historical case beside the live one.
  --
  -- ★ RETURNING gives us the initiator of the case actually settled HERE. A separate SELECT could
  -- name a case this call did not touch — one already halted, one from a prior rejected attempt, or
  -- one halted by a concurrent transaction — and would notify the wrong person, or notify twice
  -- about a process that stopped once.
  update public.death_verification_cases
     set status = 'halted', updated_at = now()
   where estate_id = p_estate and status in ('open', 'verified')
  returning initiated_by into v_initiator;

  -- ────────────────────────────────────────────────────────────────────────────────────────────
  -- ★ PHASE 11-L — TELL THE INITIATING FIDUCIARY THAT THEIR PROCESS STOPPED.
  -- ────────────────────────────────────────────────────────────────────────────────────────────
  --
  -- ★ RECIPIENT COMES FROM WORKFLOW STATE, NEVER FROM A CALLER. `p_estate` is the only input to
  -- this routine; there is no recipient parameter and therefore nothing for a client to point at
  -- someone else. `initiated_by` is `not null references auth.users(id)` on the case row.
  --
  -- ★ HISTORICAL INITIATOR, AND THE CASE MODEL SETTLES IT RATHER THAN A GUESS. 0052 states that
  -- `initiator_designation_id` / `initiator_capacity` are "a snapshot of fact ('this person acted
  -- as executor'), never an authority the case can later re-assert — a revoked designee does not
  -- keep acting because a case remembers them." So a designation revoked after initiation must NOT
  -- suppress this message: the notification asserts no authority, it reports one fact about
  -- something the recipient personally did. They already know they initiated it; being told it
  -- stopped discloses nothing they did not bring with them. Re-deriving a LIVE designation here
  -- would instead silently drop the message for exactly the person owed it.
  --
  -- ★ IT CANNOT REACH THE OWNER. The owner is the caller (is_estate_owner above), and the guard
  -- below excludes them explicitly. That covers the degenerate case where an estate owner is also
  -- a designee on their own estate: they would otherwise receive claimant-facing copy about their
  -- own halt, which reads as a message from a stranger about their own death process.
  --
  -- ★ NO DEEP LINK, DELIBERATELY. The recipient's own surface is `/executor`
  -- (`get_executor_workspace`, which refuses a revoked designee) — but the RN deep-link allowlist
  -- in `features/notifications/actions.ts` has no `afterworth://executor` key, and a link that is
  -- not in the allowlist resolves to null and renders as a non-navigating row anyway. Passing an
  -- unmatched string would be inventing a route rather than using one. Wiring that destination is
  -- a bounded mobile follow-up, recorded in docs/phase11l-halt-notification.md §6.
  --
  -- ★ EMISSION IS INSIDE THIS TRANSACTION, so it commits with the halt or not at all — no
  -- notification can precede or outlive the state change it describes. The idempotent-replay
  -- return above happens BEFORE any of this, so a second challenge emits nothing. And when no case
  -- was open, `v_initiator` is null and nothing is emitted: a halt with no initiated process to
  -- report has nobody to report it to.
  if v_initiator is not null and v_initiator <> v_uid then
    perform public.emit_lifecycle_notification(
      v_initiator, p_estate, 'death_process.halted', null);
  end if;

  -- ★ NO PROVENANCE. The fact recorded is THAT the owner challenged and from which state — never
  -- a channel, a device, an address, or a location (§17: provenance is security-sensitive
  -- information about a living owner).
  perform public.write_audit(
    'death_process.challenged', 'estate_lifecycle', null, p_estate,
    jsonb_build_object('severity', 'high', 'from_state', v_state));
  return 'challenge_halted';
end $function$;
revoke execute on function public.challenge_death_process(uuid) from public, anon;
grant  execute on function public.challenge_death_process(uuid) to authenticated;

comment on function public.challenge_death_process(uuid) is
  'The owner challenge (Phase 11-E, R12-R14): the authenticated estate owner halts a pre-released '
  'death process in one action — no evidence, no review, no waiting, no designation. Wins ties '
  '(release requires the window strictly elapsed; both serialize on the lifecycle row lock). '
  'Produces challenge_halted, terminal in 11-E. Records no provenance beyond the act itself.';

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- release_estate — REMOVED IN PHASE 11-F. Its replacement is `authorize_release` above.
-- ────────────────────────────────────────────────────────────────────────────────────────────────
--
-- ★ REMOVED FROM SOURCE, AND DROPPED BY MIGRATION 0055 — both halves are required. 11-E's
-- `release_estate(uuid)` released on ONE operator's say-so, which D1 forbids. Deleting only the
-- source would leave the function alive in every database that ever applied 11-E, because
-- `create or replace` cannot remove what it no longer mentions; dropping only in the migration
-- would let the next bundle paste recreate it from source. So the definition is gone from here and
-- the drop ships in the migration beside it — the 0053 precedent, applied to an actor rather than
-- to an argument.
--
-- A caller that was never rewired now fails loudly (`function does not exist`) instead of quietly
-- releasing an estate without a second reviewer.

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- get_owner_safety_status(p_estate) → text                          [authenticated, owner-gated]
-- ────────────────────────────────────────────────────────────────────────────────────────────────
--
-- The owner-facing presentation of their own estate's safety state — a CLOSED four-value union,
-- deliberately coarser than the lifecycle: the owner surface needs "is there something to halt",
-- never the machine's internals. An owner is authorized to know this about their own estate; no
-- one else may ask (same byte-identical refusal discipline as the challenge).
--
--   none          nothing to challenge (no death process, or it concluded without release)
--   challengeable a death process is underway and the owner may halt it
--   halted        the owner (or a prior challenge) halted the process
--   released      the process completed; the owner arrived too late to halt (stated honestly)
create or replace function public.get_owner_safety_status(p_estate uuid)
 returns text
 language plpgsql
 security definer
 stable
 set search_path to 'public'
as $function$
declare
  v_uid   uuid := auth.uid();
  v_state text;
begin
  if v_uid is null then
    raise exception 'auth_required' using errcode = '42501';
  end if;
  if not public.is_estate_owner(p_estate) then
    raise exception 'not_authorized' using errcode = '42501';
  end if;

  v_state := public.estate_lifecycle_state(p_estate);
  -- ★ THE 11-F STATE JOINS THE `challengeable` GROUP, and that is the safety-preserving mapping:
  -- an owner who has just received the email is squarely in the population this surface exists for.
  -- The union stays four values on purpose — the owner needs "can I stop this", never the machine's
  -- internals, and a client that could distinguish dispatched from windowed would be a client with
  -- something to branch on.
  return case v_state
    when 'death_verification_pending'    then 'challengeable'
    when 'death_verified'                then 'challengeable'
    when 'owner_notification_dispatched' then 'challengeable'
    when 'challenge_window'              then 'challengeable'
    when 'challenge_halted'              then 'halted'
    when 'released'                      then 'released'
    else 'none'
  end;
end $function$;
revoke execute on function public.get_owner_safety_status(uuid) from public, anon;
grant  execute on function public.get_owner_safety_status(uuid) to authenticated;

comment on function public.get_owner_safety_status(uuid) is
  'Owner-scoped safety status (Phase 11-E): a closed presentation union (none / challengeable / '
  'halted / released) over the authoritative lifecycle, for the challenge surface. Owner-only; '
  'every other caller refuses byte-identically. Not an authorization and not a disclosure: it '
  'answers about the process, never about estate content.';


-- ==== db/functions/outbox_safety.sql ==============================================================
-- ════════════════════════════════════════════════════════════════════════════════════════════════
-- PHASE 11-F · OUTBOX SAFETY — age gate, stale protection, and a purge that cannot be silent
-- ════════════════════════════════════════════════════════════════════════════════════════════════
--
-- ★ WHY A SAFETY NOTICE NEEDS DIFFERENT RULES FROM AN INVITATION EMAIL. `invitation_delivery_outbox`
-- is drained daily and its claim predicate has NO age bound: any `queued` row is claimable whenever
-- the worker next runs. For an invitation that is merely late. For the notice that tells a living
-- owner a process is running to release their estate, sending it three weeks after the fact is
-- worse than not sending it — the situation it describes has already resolved, and the message
-- would arrive as a false alarm about a window that closed, or a true alarm nobody can act on.
--
-- ★ SO STALENESS IS A DECISION, MADE ONCE, RECORDED. A notice older than the age gate is never
-- quietly sent and never quietly deleted: it is marked `failedPermanent` with an explicit failure
-- class, which leaves the evidence in place. Whether the estate should then still be releasable is
-- NOT this module's call — dispatch INITIATION already happened (Stage 2), and re-deciding that
-- here would be a second release authority hiding in a mail queue.
--
-- ★ AND NOTHING IS EVER SILENTLY DELETED (Stage 3). `purge_outbox_rows` writes an
-- `outbox_purge_audit` row BEFORE it deletes, in the same transaction, carrying the count and the
-- age range it removed. A purge with no audit row is impossible rather than discouraged.
--
-- Source of truth — re-apply on DB reset. Deploys with the release-authorization bundle.

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- owner_notice_age_gate() → interval                                                   [INTERNAL]
-- ────────────────────────────────────────────────────────────────────────────────────────────────
--
-- ★ DERIVED FROM THE CHALLENGE WINDOW, NOT CONFIGURED SEPARATELY. A notice is worth sending while
-- the window it announces could still matter; the window is 7 days (D2), so the gate is the window
-- plus one day of slack for a queue that fell behind. Two independently-tunable numbers would drift
-- apart, and the failure mode of that drift is a notice sent after its own window closed.
--
-- Fail-closed: an unconfigured window yields NULL, and a NULL gate makes `claim_owner_notices`
-- refuse to claim anything rather than treat everything as fresh.
create or replace function public.owner_notice_age_gate()
 returns interval
 language sql
 security definer
 stable
 set search_path to 'public'
as $function$
  select public.challenge_window_duration() + interval '1 day';
$function$;
revoke execute on function public.owner_notice_age_gate() from public, anon, authenticated;

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- owner_notice_claim_visibility() → interval                                          [INTERNAL]
-- ────────────────────────────────────────────────────────────────────────────────────────────────
--
-- ★ PHASE 11-OBR / OB-1. How long a claim is believed before the row is handed to another worker.
--
-- Derived from measured ceilings, not chosen for roundness: the provider request timeout is 10s
-- (`REQUEST_TIMEOUT_MS`), retried at most once on an ambiguous answer, so one row can legitimately
-- occupy a worker for ~20s; the drain runs on a serverless function whose execution ceiling is at
-- most 300s. One hour is therefore 12× the highest possible platform ceiling and ~180× the real
-- per-row cost — a row still `processing` an hour later is not slow, it is abandoned.
--
-- The upper bound matters as much: the stale sweep settles rows at `age_gate` (window + 1 day) and
-- the cron runs daily, so one hour leaves every one of those daily drains available as a recovery
-- opportunity instead of spending the gate waiting.
--
-- ★ IT IS A FUNCTION SO THERE IS EXACTLY ONE COPY. `claim_owner_notices` decides what to reclaim and
-- `owner_notice_census` reports how much is reclaimable; two literals would be two opinions about
-- the same bytes, and the first time they drifted the census would quietly stop describing what the
-- drain actually does. Not a policy table: the challenge window is a PRODUCT decision an operator
-- must be able to state, whereas this is an operational property of this worker whose only failure
-- mode is being set below the platform ceiling — which would reclaim rows out from under live
-- workers and manufacture the duplicate sends this module exists to avoid.
create or replace function public.owner_notice_claim_visibility()
 returns interval
 language sql
 immutable
 set search_path to 'public'
as $function$
  select interval '1 hour';
$function$;
revoke execute on function public.owner_notice_claim_visibility() from public, anon, authenticated;

comment on function public.owner_notice_claim_visibility() is
  'How long an owner-notice claim is believed before the row may be reclaimed (Phase 11-OBR). One '
  'hour: 12x the highest serverless execution ceiling and ~180x the real per-row send cost, and far '
  'inside the age gate so every daily drain remains a recovery opportunity. Single-sourced so the '
  'claim routine and the census cannot disagree about what is stale.';

comment on function public.owner_notice_age_gate() is
  'How old an owner safety notice may be and still be worth sending (Phase 11-F): the challenge '
  'window plus one day of queue slack, DERIVED so the two cannot drift apart. NULL when the window '
  'is unconfigured, which makes the claim routine refuse rather than treat everything as fresh.';

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- claim_owner_notices(p_max) → setof                                                   [INTERNAL]
-- ────────────────────────────────────────────────────────────────────────────────────────────────
--
-- The claim side of the owner-notice channel, with the age gate applied BEFORE anything is handed
-- to a sender. Two populations leave the queue on every call:
--
--   · STALE  — older than the gate. Marked `failedPermanent`, class `stale_beyond_age_gate`. Never
--              sent, never deleted. The row is the evidence that the owner was not reached in time,
--              which an operator investigating a disputed release will want.
--   · FRESH  — claimed for delivery with `for update skip locked`, so two concurrent drains never
--              hand the same notice out twice.
--
-- ★ PHASE 11-K WIRED THE CRON. 11-F's note read: "NO CRON IS WIRED TO THIS IN 11-F, DELIBERATELY.
-- Enabling a new delivery path is a deployment decision with its own operator step, and the phase
-- brief's own instruction is to build the safety BEFORE enabling the path. The routine exists, is
-- tested, and waits." The safety was built; 11-K enables the path. The drain is
-- `lib/ownerNotices/drain.ts`, reached by `GET /api/claims/drain_outboxes` under CRON_SECRET, and it
-- claims through this routine as `service_role` — the grant is at the foot of this section.
--
-- ★ THE ROUTE NAME IS NOT `drain_owner_notices`, AND THIS COMMENT USED TO SAY IT WAS. There is no
-- such endpoint: it returns 404 in production, verified by probing it. `drain_owner_notices` is only
-- the LOG LABEL for the owner-notice half inside the shared dispatcher. The half shares the claims
-- cron slot because Vercel Hobby permits exactly two cron jobs, so it could never have its own path.
-- A comment naming a 404 is not cosmetic in THIS module: §5/§7 of the deployment doc verify the
-- channel by probing it, and an engineer who probes the name written here gets a 404 and concludes
-- the drain was never deployed — a false negative about the only independent channel that warns a
-- living owner their estate is being released.
create or replace function public.claim_owner_notices(p_max int default 25)
 returns table (id uuid, estate_id uuid, recipient text, notice_kind text)
 language plpgsql
 security definer
 set search_path to 'public'
as $function$
declare
  v_gate interval;
  v_max  int;
  -- ★ PHASE 11-OBR / OB-1 — the claim visibility timeout, read from the ONE place that defines it
  -- (`owner_notice_claim_visibility()`), so this routine and `owner_notice_census` can never
  -- disagree about which rows are stale.
  v_visibility interval := public.owner_notice_claim_visibility();
begin
  v_gate := public.owner_notice_age_gate();
  if v_gate is null then
    -- Fail-closed: with no configured window there is no defensible notion of "too old", so the
    -- queue is not drained at all rather than drained by a guess.
    raise exception 'owner_notice_age_gate_unconfigured' using errcode = 'P0001';
  end if;
  v_max := least(greatest(coalesce(p_max, 25), 1), 100);

  -- STALE FIRST, so a stale row can never be claimed for sending by the same call.
  update public.owner_notice_outbox o
     set status = 'failedPermanent',
         failure_class = 'stale_beyond_age_gate',
         next_attempt_at = null
   where o.status in ('queued', 'processing')
     and o.requested_at < now() - v_gate;

  -- ────────────────────────────────────────────────────────────────────────────────────────────
  -- ★ THE CLAIM SET IS CLOSED AND WRITTEN OUT AS TWO NAMED BRANCHES (OB-1).
  -- ────────────────────────────────────────────────────────────────────────────────────────────
  --
  --   A · queued           — claimable immediately, subject to its backoff. Unchanged.
  --   B · processing, stale — claimed by a worker that never settled it. Reclaimable ONLY once the
  --                           claim is older than the visibility timeout.
  --
  -- Every other status is excluded, and excluded BY NAME rather than by falling through a
  -- `status <> terminal` predicate. `dispatched`, `outcomeUncertain`, `failedPermanent` and
  -- `cancelled` are all settled: two of them are terminal precisely because the message may already
  -- be in the owner's inbox, and a broad "not terminal" test is exactly how a future status added to
  -- the CHECK constraint would silently become re-sendable.
  --
  -- ★ `claimed_at IS NULL` ON A `processing` ROW IS RECLAIMABLE, AND THAT IS A DECISION.
  -- Such a row was claimed before `claimed_at` existed (migration 0057), which means it has been
  -- sitting in `processing` since at least the deployment — already far beyond any timeout. Treating
  -- NULL as "infinitely stale" is what lets the DEPLOYED mechanism recover the rows the defect
  -- already stranded, rather than requiring a hand-written repair for each one. It is a class rule;
  -- no row is named.
  --
  -- ★ WHAT A RECLAIM COSTS, STATED HONESTLY. A reclaimed row is re-sent under the SAME deterministic
  -- `Idempotency-Key` (`afterworth/owner-notice/<row id>`, built in `lib/ownerNotices/drain.ts` from
  -- the row id with no generation counter), so the provider is asked to no-op a repeat. That is the
  -- same operation the worker ALREADY performs when it retries an ambiguous first attempt — this
  -- does not re-mint a message, it replays one. It is nevertheless AT-LEAST-ONCE, not exactly-once:
  -- the provider's dedupe retention is a vendor property this repository does not pin, and a reclaim
  -- that lands outside it could produce a second copy. See docs/phase11ob-owner-notice-delivery-defect.md.
  return query
  with candidate as (
    select o.id
      from public.owner_notice_outbox o
     where o.requested_at >= now() - v_gate
       and (
         -- A · the ordinary queue
         (o.status = 'queued'
          and (o.next_attempt_at is null or o.next_attempt_at <= now()))
         -- B · an abandoned claim
         or (o.status = 'processing'
             and (o.claimed_at is null or o.claimed_at < now() - v_visibility))
       )
     order by o.requested_at
     limit v_max
     for update skip locked
  )
  update public.owner_notice_outbox o
     set status     = 'processing',
         attempts   = o.attempts + 1,
         -- Stamped on EVERY claim, first or repeat: the timeout must run from THIS claim, or a
         -- reclaimed row would be instantly reclaimable again by the next concurrent drain.
         claimed_at = now()
    from candidate c
   where o.id = c.id
  returning o.id, o.estate_id, o.recipient, o.notice_kind;
end $function$;
-- ★ THE WORKER GRANT (11-K), AND WHY IT IS NOT `authenticated`. Claiming is a WORKER act, not an
-- operator act: it moves a live safety message into `processing` and hands it to a sender. An
-- operator who could claim could also strand a notice in `processing`, where the stale sweep will
-- eventually mark it failedPermanent — an owner silently un-notified by a console click. The 0043
-- precedent exactly: the claim/record pair is service_role only, revoked from every client role.
revoke execute on function public.claim_owner_notices(int) from public, anon, authenticated;
grant  execute on function public.claim_owner_notices(int) to service_role;

comment on function public.claim_owner_notices(int) is
  'Claims owner safety notices for delivery, applying the age gate FIRST (Phase 11-F, Stage 3): '
  'rows older than the gate are marked failedPermanent/stale_beyond_age_gate and are never sent and '
  'never deleted. Fresh rows are claimed with skip-locked so concurrent drains cannot double-send. '
  'Refuses entirely when the age gate is unconfigured. service_role ONLY (Phase 11-K wired the '
  'drain); no client role may claim.';

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- record_owner_notice_outcome(p_id, p_outcome, p_failure_class) → text            [service_role]
-- ────────────────────────────────────────────────────────────────────────────────────────────────
--
-- ★ THE HALF 11-F LEFT OUT, AND THE REASON A DRAIN COULD NOT BE WRITTEN UNTIL NOW.
-- `claim_owner_notices` moves a row to `processing` and returns it. Nothing wrote back what the
-- sender then learned — so any worker built on the 11-F schema would have claimed rows and stranded
-- every one of them in `processing`, where the stale sweep would later mark them failedPermanent.
-- The queue would have looked drained and no owner would have been reached.
--
-- Modelled on `record_invitation_delivery_outcome` (0043) with three deliberate differences, each
-- forced by what THIS channel is for:
--
--   · NO GENERATION GUARD, because there is no generation column and no reissue concept. A safety
--     notice is dispatched once, by one transition, and is never re-minted. What replaces the guard
--     is the settled-status check below: a row that has already settled is a no-op.
--
--   · NO PROVIDER MESSAGE ID IS STORED. The table has no column for one and gains none. A provider
--     handle is a lookup key into a third party's log of a message addressed to a living owner; the
--     operational fact this product needs is the outcome, and that is what is recorded.
--
--   · A LOWER CAP AND A SHORTER BACKOFF. Invitations retry 5 times with up to 12h between attempts,
--     which is right for a message that is merely late. This notice is only worth sending inside
--     the age gate (window + 1 day), so a 12h backoff would spend the whole gate on two attempts.
--     Three attempts at ~1h/2h/3h all land comfortably inside it.
--
-- ★ ACCEPTED AND UNCERTAIN ARE BOTH TERMINAL, for the same reason: the message may already be in
-- the owner's inbox, and this product will not send a second copy of a notice about their own death
-- on the strength of a lost HTTP response. Only `retryPending` — where the provider ANSWERED and
-- refused, proving nothing was accepted — returns a row to `queued`.
create or replace function public.record_owner_notice_outcome(
  p_id            uuid,
  p_outcome       text,
  p_failure_class text default null
)
 returns text
 language plpgsql
 security definer
 set search_path to 'public'
as $function$
declare
  v_row    public.owner_notice_outbox%rowtype;
  v_status text;
  v_next   timestamptz;
  v_class  text;
  c_max_attempts constant int := 3;
begin
  if p_outcome not in ('providerAccepted', 'outcomeUncertain', 'retryPending', 'failedPermanent') then
    raise exception 'invalid_outcome' using errcode = 'P0001';
  end if;

  select * into v_row from public.owner_notice_outbox where id = p_id for update;
  if not found then
    raise exception 'outbox_entry_not_found' using errcode = 'P0002';
  end if;

  -- Already settled: report current state, change nothing, write no second audit row. Covers a
  -- duplicate callback and an operator-cancelled row alike.
  if v_row.status in ('dispatched', 'outcomeUncertain', 'failedPermanent', 'cancelled') then
    return v_row.status;
  end if;

  v_class := case when p_outcome in ('retryPending', 'failedPermanent') then p_failure_class else null end;
  v_next  := null;

  if p_outcome = 'providerAccepted' then
    v_status := 'dispatched';
  elsif p_outcome = 'outcomeUncertain' then
    v_status := 'outcomeUncertain';
  elsif p_outcome = 'failedPermanent' then
    v_status := 'failedPermanent';
  else
    if v_row.attempts >= c_max_attempts then
      v_status := 'failedPermanent';
      v_class  := coalesce(v_class, 'retry_cap_exhausted');
    else
      v_status := 'queued';
      v_next   := now() + make_interval(hours => least(greatest(v_row.attempts, 1), 3));
    end if;
  end if;

  -- ★ PHASE 11-OC — ACCEPTANCE IS STAMPED IN THIS ONE STATEMENT, BESIDE THE STATUS IT AGREES WITH.
  --
  -- `notice_accepted_at` is the fact Phase D makes release-authoritative, and it is written here and
  -- nowhere else. One UPDATE, so `dispatched` + NULL acceptance is structurally unreachable for any
  -- row written after Phase A — which is what lets the re-notice routine treat that combination as
  -- an unambiguous LEGACY marker rather than as a state it might have produced itself.
  --
  -- ★ IT IS KEYED ON `p_outcome`, NOT ON `v_status`. They agree today: `providerAccepted` is the only
  -- branch that yields `dispatched`. Keying on the OUTCOME ties the stamp to what the provider
  -- actually reported, so if a future branch ever reaches `dispatched` by another route it does not
  -- silently inherit an acceptance fact nobody established. `outcomeUncertain`, `retryPending` and
  -- `failedPermanent` all leave it NULL — an unknown outcome must never be recorded as an acceptance,
  -- which is the whole reason this column exists rather than a status list.
  --
  -- First-write-wins needs no `where notice_accepted_at is null` guard: the settled-status no-op
  -- above already makes a second settle unreachable, and a redundant guard here would mask a future
  -- change to that no-op instead of failing beside it.
  update public.owner_notice_outbox
     set status             = v_status,
         failure_class      = v_class,
         next_attempt_at    = v_next,
         dispatched_at      = case when v_status = 'dispatched' then now() else dispatched_at end,
         notice_accepted_at = case when p_outcome = 'providerAccepted' then now()
                                   else notice_accepted_at end
   where id = p_id;

  -- ★ THE AUDIT NAMES THE OUTCOME AND THE CHANNEL CLASS, NEVER THE ADDRESS — the same discipline as
  -- the dispatch audit it follows. An audit row outlives every reason anyone had to read it.
  -- actor_id is NULL because the actor is a scheduled worker, not a person; `source = 'worker'`
  -- says so without inventing a synthetic operator identity.
  insert into public.audit_logs (actor_id, estate_id, action, target_table, target_id, metadata, source)
  values (null, v_row.estate_id, 'death_process.owner_notice_outcome', 'owner_notice_outbox', p_id,
          jsonb_build_object('severity', 'high', 'outcome', v_status,
                            'failure_class', v_class, 'attempts', v_row.attempts,
                            'channel', v_row.channel, 'notice_kind', v_row.notice_kind),
          'worker');
  return v_status;
end $function$;
revoke execute on function public.record_owner_notice_outcome(uuid, text, text)
  from public, anon, authenticated;
grant  execute on function public.record_owner_notice_outcome(uuid, text, text) to service_role;

comment on function public.record_owner_notice_outcome(uuid, text, text) is
  'Write-back half of the owner-safety notice drain (Phase 11-K). providerAccepted -> dispatched; '
  'retryPending -> queued with backoff until a 3-attempt cap, then failedPermanent; '
  'outcomeUncertain and failedPermanent are terminal. An already-settled row is a no-op, so a '
  'duplicate callback can never produce a second send. Records no recipient address. service_role only.';

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- purge_outbox_rows(p_outbox, p_before, p_reason) → int                       [admin, AAL2+fresh]
-- ────────────────────────────────────────────────────────────────────────────────────────────────
--
-- ★ THE AUDIT ROW IS WRITTEN BEFORE THE DELETE, IN THE SAME TRANSACTION. Not after — an audit
-- written afterwards is an audit that a failure can skip, leaving rows gone and no record of who
-- removed them or why. Here the audit and the deletion commit together or neither happens.
--
-- ★ A REASON IS REQUIRED AND CANNOT BE BLANK. "Cleaning up" is not a reason; the column exists so
-- that someone reconstructing a disputed release a year later can tell a routine hygiene sweep from
-- a deletion that removed the evidence of an owner who was never reached.
--
-- ★ IT REFUSES TO TOUCH ROWS THAT ARE STILL ACTIONABLE. `queued` and `processing` notices are live
-- safety messages; purging those would be deleting an owner's warning while it is still in flight.
-- Only settled rows (dispatched / failedPermanent / cancelled) can be purged, and only ones older
-- than an explicit cutoff the caller states.
create or replace function public.purge_outbox_rows(
  p_outbox text,
  p_before timestamptz,
  p_reason text
)
 returns int
 language plpgsql
 security definer
 set search_path to 'public'
as $function$
declare
  v_uid    uuid;
  v_count  int;
  v_oldest timestamptz;
  v_newest timestamptz;
  v_audit  uuid;
begin
  perform public.admin_require_gate();
  v_uid := auth.uid();

  if p_reason is null or btrim(p_reason) = '' then
    raise exception 'purge_reason_required' using errcode = 'P0001';
  end if;
  if p_before is null then
    raise exception 'purge_cutoff_required' using errcode = 'P0001';
  end if;
  -- A closed vocabulary of purgeable outboxes. An unknown name is refused rather than resolved
  -- dynamically: `execute format('delete from %I')` on a caller-supplied table is how an admin
  -- routine becomes a general-purpose delete.
  if p_outbox is distinct from 'owner_notice_outbox' then
    raise exception 'unknown_outbox' using errcode = 'P0001';
  end if;

  select count(*), min(requested_at), max(requested_at)
    into v_count, v_oldest, v_newest
    from public.owner_notice_outbox
   where status in ('dispatched', 'failedPermanent', 'cancelled')
     and requested_at < p_before;

  if v_count = 0 then
    return 0; -- nothing to purge writes no audit row: an audit of a no-op is noise, not evidence
  end if;

  insert into public.outbox_purge_audit
    (outbox_name, actor_id, row_count, oldest_row_at, newest_row_at, reason)
  values (p_outbox, v_uid, v_count, v_oldest, v_newest, p_reason)
  returning id into v_audit;

  -- Stamp the audit id onto the rows first, so even a partial failure leaves the link.
  update public.owner_notice_outbox
     set purge_audit_id = v_audit
   where status in ('dispatched', 'failedPermanent', 'cancelled')
     and requested_at < p_before;

  delete from public.owner_notice_outbox
   where status in ('dispatched', 'failedPermanent', 'cancelled')
     and requested_at < p_before;

  insert into public.audit_logs (actor_id, estate_id, action, target_table, target_id, metadata, source)
  values (v_uid, null, 'outbox.purged', 'outbox_purge_audit', v_audit,
          jsonb_build_object('severity', 'high', 'outbox', p_outbox, 'row_count', v_count,
                            'oldest_row_at', v_oldest, 'newest_row_at', v_newest,
                            'reason', p_reason),
          'admin');
  return v_count;
end $function$;
revoke execute on function public.purge_outbox_rows(text, timestamptz, text) from public, anon;
grant  execute on function public.purge_outbox_rows(text, timestamptz, text) to authenticated;

comment on function public.purge_outbox_rows(text, timestamptz, text) is
  'Purges SETTLED owner-notice rows older than an explicit cutoff (Phase 11-F, Stage 3). Writes the '
  'outbox_purge_audit row BEFORE deleting, in the same transaction, so a silent purge is impossible. '
  'Requires a non-blank reason, refuses an unknown outbox name, and never touches queued or '
  'processing rows — those are live safety messages still in flight.';

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- owner_notice_census() → jsonb                                                [admin, AAL2+fresh]
-- ────────────────────────────────────────────────────────────────────────────────────────────────
--
-- The read-only classification Stage 3 requires before any delivery path is enabled: totals, status
-- distribution, age distribution, and the actionable/stale split — computed against the CURRENT age
-- gate rather than against a remembered one. Counts only; no recipient address, no estate name.
create or replace function public.owner_notice_census()
 returns jsonb
 language plpgsql
 security definer
 stable
 set search_path to 'public'
as $function$
declare v_gate interval; v_out jsonb;
begin
  perform public.admin_require_gate();
  v_gate := public.owner_notice_age_gate();

  -- ★ TWO SEPARATE AGGREGATIONS, COMBINED — NOT A LATERAL JOIN. The first draft joined a
  -- per-status GROUP BY laterally onto the row set, which returns every status group for EVERY row:
  -- three rows across three statuses became nine, and `total` reported 9. The status map looked
  -- right (duplicate keys resolve last-wins), so a test asserting only the presence of keys passed
  -- while the headline number was triple the truth. A census whose total is wrong is worse than no
  -- census — it is the number an operator would quote when deciding whether to purge.
  with rows as (
    select o.status, o.requested_at, o.claimed_at,
           -- ★ PHASE 11-OC. The three facts that make the Phase D blast radius countable.
           o.notice_accepted_at, o.case_id, o.superseded_by, o.generation
      from public.owner_notice_outbox o
  ),
  by_gen as (
    select coalesce(jsonb_object_agg(t.generation::text, t.n), '{}'::jsonb) as m
      from (select r.generation, count(*) as n from rows r group by r.generation) t
  ),
  by_status as (
    select coalesce(jsonb_object_agg(t.status, t.n), '{}'::jsonb) as m
      from (select r.status, count(*) as n from rows r group by r.status) t
  )
  select jsonb_build_object(
    'total', (select count(*) from rows),
    'by_status', (select m from by_status),
    'age_gate', v_gate::text,
    'oldest_requested_at', (select min(r.requested_at) from rows r),
    'newest_requested_at', (select max(r.requested_at) from rows r),
    'actionable', (select count(*) from rows r
                    where r.status = 'queued'
                      and v_gate is not null and r.requested_at >= now() - v_gate),
    'stale', (select count(*) from rows r
               where r.status in ('queued', 'processing')
                 and v_gate is not null and r.requested_at < now() - v_gate),
    -- ★ 11-K: without this key an `outcomeUncertain` row would appear in `total` and `by_status`
    -- and in NONE of the three splits, so an operator reconciling actionable+stale+purgeable
    -- against the total would find a gap with no name — and a nameless gap in a safety queue is
    -- the number someone eventually explains away. It is counted separately rather than folded
    -- into `purgeable` because it is deliberately NOT purgeable.
    'uncertain', (select count(*) from rows r where r.status = 'outcomeUncertain'),
    'purgeable', (select count(*) from rows r
                   where r.status in ('dispatched', 'failedPermanent', 'cancelled')),
    -- ★ PHASE 11-OBR / OB-1 — THE STUCK-CLAIM SPLIT, WITHOUT WHICH THIS DEFECT IS INVISIBLE.
    --
    -- The Branch A notice sat at `processing` for a day and nothing anywhere said so: `by_status`
    -- carried a `processing: 1` that reads as healthy in-flight work, and there was no way to ask
    -- how long it had been in flight. These three keys are what turn "a notice is being sent" into
    -- "a notice has been abandoned", which is a different operational fact entirely.
    --
    -- `processing_stale` uses the SAME predicate the drain reclaims by — including its NULL branch —
    -- read from `owner_notice_claim_visibility()` rather than restated, so this number is exactly
    -- "rows the next drain will pick up" and not an approximation of it.
    'processing_total', (select count(*) from rows r where r.status = 'processing'),
    'processing_stale', (select count(*) from rows r
                          where r.status = 'processing'
                            and (r.claimed_at is null
                                 or r.claimed_at < now() - public.owner_notice_claim_visibility())),
    -- Age of the OLDEST claim still in flight, as an interval string. NULL when nothing is
    -- processing. A legacy row with no claimed_at cannot have an age computed, so it reports NULL
    -- here and is counted in `processing_stale` above — the count is the alarm, this is the detail.
    'oldest_processing_age', (select (now() - min(r.claimed_at))::text from rows r
                               where r.status = 'processing' and r.claimed_at is not null),
    -- ────────────────────────────────────────────────────────────────────────────────────────
    -- ★ PHASE 11-OC — THE ACCEPTANCE AND EPISODE SPLITS.
    -- ────────────────────────────────────────────────────────────────────────────────────────
    --
    -- These four keys are what make the Phase D blast radius a NUMBER instead of an argument. They
    -- follow the `uncertain` key's discipline exactly: every row must land in a NAMED split, because
    -- a nameless gap in a safety queue is the number someone eventually explains away.
    --
    -- The reconciliation an operator can perform, and which the suite asserts:
    --
    --   accepted_total + unaccepted_total            = total
    --   legacy_unaccepted ⊆ unaccepted_total         (it is the `dispatched` slice of it)
    --   sum(by_generation values)                    = total
    --
    -- `accepted_total` counts the FACT, not the status: a row is accepted because a provider
    -- acceptance was stamped on it, never because it reached some status.
    'accepted_total',   (select count(*) from rows r where r.notice_accepted_at is not null),
    'unaccepted_total', (select count(*) from rows r where r.notice_accepted_at is null),
    -- ★ THE LEGACY POPULATION, PRECISELY. `dispatched` with no acceptance fact is the shape that
    -- existed before Phase A and is structurally unreachable after it (status and acceptance are
    -- written in one UPDATE). A non-zero count here is therefore a count of PRE-PHASE-A rows, which
    -- is exactly the population Phase D would refuse and Phase C must remediate.
    'legacy_unaccepted', (select count(*) from rows r
                           where r.status = 'dispatched' and r.notice_accepted_at is null),
    -- Rows that belong to no episode. Also strictly pre-Phase-A: the INSERT trigger refuses a NULL
    -- case_id, so this can only shrink.
    'no_episode',       (select count(*) from rows r where r.case_id is null),
    'superseded_total', (select count(*) from rows r where r.superseded_by is not null),
    'current_total',    (select count(*) from rows r where r.superseded_by is null),
    'by_generation',    (select m from by_gen)
  ) into v_out;

  return v_out;
end $function$;
revoke execute on function public.owner_notice_census() from public, anon;
grant  execute on function public.owner_notice_census() to authenticated;

comment on function public.owner_notice_census() is
  'Read-only owner-notice outbox classification (Phase 11-F, Stage 3): totals, status and age '
  'distribution, and the actionable/stale/purgeable split against the CURRENT age gate. Phase 11-OC '
  'adds the acceptance and episode splits (accepted_total, legacy_unaccepted, no_episode, '
  'superseded_total, by_generation), each reconciling against total with no nameless gap. Counts '
  'only — never a recipient address. Admin-gated.';

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- owner_notice_release_readiness_census() → jsonb                            [admin, AAL2+fresh]
-- ────────────────────────────────────────────────────────────────────────────────────────────────
--
-- ★ PHASE 11-OC · THE BLAST RADIUS, AS A NUMBER, BEFORE THE POLICY THAT CREATES IT.
--
-- `owner_notice_census` counts ROWS. This counts ESTATES AT THE DOOR — the population Phase D's
-- stricter release predicate will actually judge — classified by the state of the CURRENT generation
-- of the CURRENT case episode. It exists so the Phase D cutover decision is made against a measured
-- count rather than an assumption, and so the class that needs the Phase C remedy is named before it
-- is blocked.
--
-- ★ IT IS SCOPED EXACTLY AS THE PHASE D PREDICATE WILL BE, OR IT WOULD BE MEASURING SOMETHING ELSE.
-- Current case episode (`status = 'verified'`, newest `decided_at`), current generation
-- (`superseded_by is null`), email channel, window-opened kind. A census that aggregated by estate
-- would count an accepted notice from a prior REJECTED case as readiness for a new one — which is
-- the exact defect Phase D exists to close, reproduced in the instrument built to measure it.
--
-- ★ EVERY ESTATE LANDS IN EXACTLY ONE NAMED BUCKET, AND THE BUCKETS RECONCILE AGAINST THE TOTAL.
-- The `uncertain` discipline again: a nameless remainder is the number someone explains away. The
-- suite asserts the sum, so a future status that fell through would break the reconciliation rather
-- than hide in it.
--
-- ★ TWO ABSENCES ARE DISTINGUISHED, BECAUSE THE OPERATOR'S NEXT ACTION DIFFERS.
--   · `no_current_notice`            — no notice row names this case at all. Needs dispatch, not
--                                      re-notice. Fail-closed either way.
--   · `ambiguous_historical_linkage` — the estate HAS notice rows but they carry a NULL case_id, so
--                                      which episode they belong to is unprovable. These are
--                                      pre-Phase-A rows and are NEVER guessed into an episode; the
--                                      remedy is a re-notice that produces a fact, never a backfill
--                                      that invents one.
--
-- ★ PRIVACY-MINIMIZED BY CONSTRUCTION. Counts only. No estate id, no estate name, no case id, no
-- user id, no recipient address — on any branch. There is nothing here to correlate back to a living
-- owner, which is the point: an operator deciding a rollout needs a distribution, not a roster.
create or replace function public.owner_notice_release_readiness_census()
 returns jsonb
 language plpgsql
 security definer
 stable
 set search_path to 'public'
as $function$
declare v_out jsonb;
begin
  perform public.admin_require_gate();

  with door as (
    -- Every estate standing at the release door. `challenge_window` is the ONLY state Phase D's
    -- predicate governs; a released estate is past the door and an earlier one has not reached it.
    --
    -- ★ THE TABLE, NOT `estate_lifecycle_state()`, AND THE CHOICE IS FORCED RATHER THAN CASUAL.
    --
    -- `deathVerificationFoundation.test.ts` keeps two lists with two different privileges, and this
    -- read had to land in one of them. Going through the reader looks stricter and violates the OTHER
    -- rule in the same audit: outside the death module the reader may appear only as an argument to
    -- `release_condition_satisfied`, never in a local comparison — because
    -- `if estate_lifecycle_state(e) = '…'` is release policy leaking back out of the canonical module
    -- one `if` at a time, which that audit calls the single most likely accident here. A
    -- `where estate_lifecycle_state(e.id) = 'challenge_window'` scan is exactly that shape.
    --
    -- So this file joins `LIFECYCLE_TABLE_READERS`, the list `operator_console.sql` already occupies
    -- for the same reason: an operator PROJECTION that reports where the machine stands. Membership
    -- carries a proof obligation the other lists do not — the audit asserts every member is READ-ONLY
    -- against the lifecycle — and this file satisfies it: the census is `stable`, selects only, and
    -- names no transition, no lifecycle UPDATE and no INSERT.
    select l.estate_id
      from public.estate_lifecycle l
     where l.state = 'challenge_window'
  ),
  cur_case as (
    -- The CURRENT episode key, resolved exactly as authorize_release resolves it.
    select d.estate_id,
           (select c.id from public.death_verification_cases c
             where c.estate_id = d.estate_id and c.status = 'verified'
             order by c.decided_at desc limit 1) as case_id
      from door d
  ),
  cur_gen as (
    select cc.estate_id,
           cc.case_id,
           o.status,
           -- ★ ACCEPTANCE IS AN EXISTENTIAL OVER THE WHOLE EPISODE, NEVER A PROPERTY OF THE CURRENT
           -- GENERATION — and this census got that wrong on its first draft, which its own direction-1
           -- positive control caught.
           --
           -- The door asks "did ANY generation of this episode reach provider acceptance?". Reading
           -- only the current generation implements "latest generation only", which the architecture
           -- rejects explicitly: an already-accepted generation 1 would STOP qualifying the moment a
           -- generation 2 was created, so issuing a notice would REMOVE release authority and hand an
           -- operator a lever that suppresses a release. Authority is monotone — creating a generation
           -- can only ever ADD it — which is the same property that makes the MIN anchor immutable.
           --
           -- This must match the Phase D predicate exactly, or the console and the door disagree about
           -- the same estate.
           --
           -- ★ PHASE C — THE EPISODE IS A KIND SET, NOT ONE LITERAL, AND THAT IS WHAT MAKES THE
           -- REMEDY VISIBLE TO THE INSTRUMENT THAT MEASURES IT. A deliberate re-notice takes
           -- `death_process.window_renotice` (migration 0059) so a second warning is never recorded
           -- as the initial window-opening event. Left as the Phase A literal, this predicate could
           -- not see a re-notice at all: a remediated estate would keep reporting as REFUSED however
           -- many times it was re-noticed, its eventual provider acceptance would never be counted,
           -- and Phase C would be inert in exactly the census built to prove Phase C works.
           --
           -- Read from `owner_notice_episode_kinds()` rather than restated, for the reason
           -- `owner_notice_claim_visibility()` gives: two literals are two opinions about the same
           -- bytes, and the door and the census must never hold different ones.
           exists (
             select 1 from public.owner_notice_outbox a
              where a.case_id = cc.case_id
                and a.channel = 'email'
                and a.notice_kind = any (public.owner_notice_episode_kinds())
                and a.notice_accepted_at is not null
           ) as accepted_any,
           -- Does the estate carry any unlinkable pre-Phase-A row? Only consulted when no current
           -- generation was found, to separate "never dispatched" from "cannot be proven".
           (select count(*) from public.owner_notice_outbox z
             where z.estate_id = cc.estate_id and z.case_id is null) as orphan_rows
      from cur_case cc
      -- Phase C: the CURRENT generation may be a re-notice, so the join reads the episode kind SET
      -- for the same reason `accepted_any` above does. Left as one literal, a remediated estate would
      -- report `no_current_notice` — an estate that has just been re-noticed described as one that
      -- was never dispatched, which is the opposite of the truth and would send an operator to
      -- dispatch a window that is already open.
      left join public.owner_notice_outbox o
        on o.case_id = cc.case_id
       and o.channel = 'email'
       and o.notice_kind = any (public.owner_notice_episode_kinds())
       and o.superseded_by is null
  ),
  classified as (
    select case
             when case_id is null                              then 'no_verified_case'
             -- ★ THE ACCEPTANCE TEST COMES FIRST, and it is the ONLY bucket that decides admission.
             -- Everything below it describes what the CURRENT generation is doing, which is
             -- diagnostic information for an operator — useful, and not the release question.
             when accepted_any                                 then 'accepted'
             when status is null and orphan_rows > 0           then 'ambiguous_historical_linkage'
             when status is null                               then 'no_current_notice'
             when status = 'dispatched'                        then 'legacy_dispatched_unaccepted'
             when status = 'outcomeUncertain'                  then 'outcome_uncertain'
             when status = 'failedPermanent'                   then 'failed_permanent'
             when status = 'queued'                            then 'queued'
             when status = 'processing'                        then 'processing'
             when status = 'cancelled'                         then 'cancelled'
             -- ★ NOT A FALL-THROUGH. A status outside the six lands HERE, by name, so a widened
             -- CHECK constraint shows up as an unclassified count instead of silently joining a
             -- neighbouring bucket. The reconciliation assertion in the suite then fails loudly.
             else 'unclassified'
           end as bucket
      from cur_gen
  )
  select jsonb_build_object(
    'estates_at_door', (select count(*) from classified),
    'by_readiness',    coalesce((select jsonb_object_agg(t.bucket, t.n)
                                   from (select bucket, count(*) as n from classified group by bucket) t),
                                '{}'::jsonb),
    -- ★ THE ONE NUMBER THE PHASE D GATE TURNS ON. Estates at the door whose current episode carries
    -- NO provable provider acceptance — i.e. exactly those Phase D would refuse with
    -- `notice_never_accepted`. If this is non-zero, Phase D must not activate for that class until
    -- the Phase C re-notice remedy is deployed and operational.
    'would_be_refused_by_phase_d',
      (select count(*) from classified where bucket <> 'accepted'),
    'would_be_admitted_by_phase_d',
      (select count(*) from classified where bucket = 'accepted'),
    -- Retained so a reader can see that the strict policy is strictly narrower than today's, without
    -- having to reason about it: today's predicate admits every estate with any non-cancelled row.
    'would_be_admitted_by_current_predicate',
      (select count(*) from classified where bucket not in ('no_verified_case', 'no_current_notice',
                                                            'cancelled'))
  ) into v_out;

  return v_out;
end $function$;
revoke execute on function public.owner_notice_release_readiness_census() from public, anon;
grant  execute on function public.owner_notice_release_readiness_census() to authenticated;

comment on function public.owner_notice_release_readiness_census() is
  'Read-only Phase 11-OC blast-radius projection: how many estates standing at the release door '
  'would be admitted or refused by the Phase D acceptance predicate, classified by the state of the '
  'CURRENT generation of the CURRENT case episode. Scoped by case exactly as the Phase D predicate '
  'is, so it cannot credit an accepted notice from a prior rejected process. Every estate lands in '
  'one NAMED bucket and the buckets reconcile against the total. Counts ONLY — no estate id, no '
  'case id, no user id, no recipient address, on any branch. Admin-gated.';

commit;
